    private static void stubRetryDao(NotifyNotificationDao dao) {
        when(dao.databaseNow()).thenReturn(java.time.LocalDateTime.of(2026, 9, 19, 0, 0, 0, 900_000_000));
        NotifyIntent intent = new NotifyIntent();
        intent.setIntentId(9L);
        intent.setStatus("FAILED");
        when(dao.lockIntent(9L)).thenReturn(intent);
        NotifyDelivery delivery = new NotifyDelivery();
        delivery.setDeliveryId(8L);
        delivery.setStatus("FAILED");
        when(dao.lockDeliveries(9L)).thenReturn(List.of(delivery));
        when(dao.markDeliveryForRetry(8L)).thenReturn(1);
        when(dao.requeueOutbox(eq(8L), any())).thenReturn(1);
        when(dao.update(any(NotifyIntent.class))).thenReturn(1);
    }

    private static NotificationCommand submitCommand() {
        return new NotificationCommand(
            "profile", "person-rebind", "PERSON_REBIND", "biz-1",
            "USER", List.of("101"), "person-rebind",
            Map.of("title", "secret-title", "content", "通知正文"),
            List.of(NotificationChannel.IN_APP),
            NotificationStrategy.ALL, NotificationMode.ASYNC, 0,
            null, null, "key-1", Map.of("token", "smtp-password"));
    }

    private static final class RecordingTransport implements NotifyOutboxWakeTransport {
        private final List<PublishedWake> published = new ArrayList<>();
        private RuntimeException failure;

        @Override
        public java.util.concurrent.Future<Long> publish(String channel, NotifyOutboxWakeSignal signal) {
            if (failure != null) {
                throw failure;
            }
            published.add(new PublishedWake(channel, signal));
            return java.util.concurrent.CompletableFuture.completedFuture(1L);
        }
    }

    private record PublishedWake(String channel, NotifyOutboxWakeSignal signal) {
    }
}

package org.namewta.notify.support.outbox;

import org.redisson.Redisson;
import org.redisson.api.RedissonClient;
import org.redisson.codec.SerializationCodec;
import org.redisson.config.Config;

/**
 * T-03 跨进程门禁的 Redis 夹具。缺连接时失败，禁止 skip 充当通过。
 */
public final class NotifyOutboxWakeRedisGate {

    private NotifyOutboxWakeRedisGate() {
    }

    /**
     * 建立独立 Redisson 客户端；连不上则抛出断言失败。
     *
     * @return 已连接的客户端，调用方负责 shutdown
     */
    public static RedissonClient connectOrFail(String role) {
        String host = setting("notify.outbox.wake.redis.host", "REDIS_HOST", "127.0.0.1");
        String portText = setting("notify.outbox.wake.redis.port", "REDIS_PORT", "6379");
        String password = setting("notify.outbox.wake.redis.password", "REDIS_PASSWORD", "");
        int port;
        try {
            port = Integer.parseInt(portText);
        } catch (NumberFormatException ex) {
            throw fail(role, host, portText, "port is not an integer");
        }
        Config config = new Config();
        config.setCodec(new SerializationCodec());
        var server = config.useSingleServer().setAddress("redis://" + host + ":" + port).setTimeout(2000);
        if (!password.isBlank()) {
            server.setPassword(password);
        }
        RedissonClient client = Redisson.create(config);
        try {
            client.getKeys().count();
            return client;
        } catch (RuntimeException ex) {
            client.shutdown();
            throw fail(role, host, portText, ex.getMessage());
        }
    }

    private static AssertionError fail(String role, String host, String port, String detail) {
        return new AssertionError(
            "AC-002 requires Redis for " + role + " at " + host + ":" + port
                + " (set REDIS_PASSWORD / notify.outbox.wake.redis.*). Do not skip. Detail: " + detail);
    }

    private static String setting(String property, String environment, String defaultValue) {
        String value = System.getProperty(property);
        if (value == null || value.isBlank()) {
            value = System.getenv(environment);
        }
        if (value == null || value.isBlank()) {
            return defaultValue;
        }
        return value.trim();
    }
}

