        requireTarget(target);
        List<NotifySceneBinding> bindings = dao.listBindingsByAccount(accountId);
        NotifySceneBinding binding = sceneCode == null || sceneCode.isBlank()
            ? bindings.stream().findFirst().orElse(null)
            : bindings.stream().filter(item -> sceneCode.equals(item.getSceneCode())).findFirst().orElse(null);
        if (binding == null) {
            throw new ServiceException("账号未绑定逻辑场景");
        }
        return submit(binding.getSceneCode(), account.getChannel(), target);
    }

    /**
     * 按场景模板试发。
     *
     * @param sceneCode 场景
     * @param channel   渠道
     * @param target    收件人
     * @return 提交状态
     */
    public String sendTemplate(String sceneCode, String channel, String target) {
        requireTarget(target);
        NotifySceneBinding binding = dao.findBinding(sceneCode, channel);
        if (binding == null || binding.getAccountId() == null) {
            throw new ServiceException("场景未绑定渠道账号");
        }
        NotifyChannelAccount account = dao.findAccount(binding.getAccountId());
        if (account == null || !"Y".equals(account.getEnabled())) {
            throw new ServiceException("渠道账号未启用或不存在");
        }
        return submit(sceneCode, channel, target);
    }

    private String submit(String sceneCode, String channel, String target) {
        String recipientType = "MAIL".equals(channel) ? "EMAIL" : "PHONE";
        NotificationChannel notifyChannel = "MAIL".equals(channel) ? NotificationChannel.MAIL : NotificationChannel.SMS;
        Map<String, Object> params = new LinkedHashMap<>();
        NotifySceneCatalog.examples(sceneCode).forEach(params::put);
        NotificationReceipt receipt = notifications.submit(new NotificationCommand(
            "notify", sceneCode, "NOTIFY_CONFIG_TEST", target, recipientType, List.of(target),
            sceneCode, params, List.of(notifyChannel), NotificationStrategy.ALL, NotificationMode.ASYNC,
            20, null, null,
            "notify-config-test:" + sceneCode + ":" + channel + ":" + System.currentTimeMillis(),
            Map.of("audit", "TEST")));
        return receipt == null || receipt.status() == null ? "UNKNOWN" : receipt.status().name();
    }

    private void requireTarget(String target) {
        if (target == null || target.isBlank()) {
            throw new ServiceException("测试收件人不能为空");
        }
    }
}

package org.namewta.notify.service;

import lombok.RequiredArgsConstructor;
import org.namewta.common.core.domain.PageResult;
import org.namewta.common.core.exception.ServiceException;
import org.namewta.common.json.utils.JsonUtils;
import org.namewta.notify.dao.NotifyPersistenceDao;
import org.namewta.notify.domain.bo.NotifyNoticeBo;
import org.namewta.notify.domain.entity.NotifyNotice;
import org.namewta.notify.domain.policy.NoticeAudiencePolicy;
import org.namewta.notify.domain.vo.NotifyNoticeVo;
import org.namewta.system.api.UserService;
import org.springframework.stereotype.Service;
import java.time.LocalDateTime;
import java.util.Arrays;
import java.util.List;

/** 公告草稿和生命周期规则，持久化操作统一经过 DAO。 */
@Service
@RequiredArgsConstructor
public class NotifyNoticeService {
    private final NotifyPersistenceDao dao;
    private final UserService userService;

    public PageResult<NotifyNoticeVo> page(NotifyNoticeBo query, Integer pageNum, Integer pageSize) {
        var page = dao.page(query, pageNum, pageSize);
        return PageResult.build(page.getRows().stream().map(this::toVo).toList(), page.getTotal());
    }

    public NotifyNoticeVo get(Long id) {
        NotifyNotice notice = dao.find(id);
        if (notice == null) throw new ServiceException("通知不存在");
        return toVo(notice);
    }

    private NotifyNoticeVo toVo(NotifyNotice entity) {
        NotifyNoticeVo vo = new NotifyNoticeVo();
        vo.setNoticeId(entity.getNoticeId());
        vo.setNoticeTitle(entity.getNoticeTitle());
        vo.setNoticeType(entity.getNoticeType());
        vo.setNoticeContent(entity.getNoticeContent());
        vo.setRecipientType(entity.getRecipientType() == null ? "ALL" : entity.getRecipientType());
        vo.setRecipientIds(JsonUtils.parseArray(entity.getRecipientIdsJson(), Long.class));
        vo.setUserTypeIds(JsonUtils.parseArray(entity.getUserTypeIdsJson(), Long.class));
        vo.setChannels(entity.getChannelsJson() == null ? List.of("IN_APP") : JsonUtils.parseArray(entity.getChannelsJson(), String.class));
        vo.setStatus(entity.getStatus());
        vo.setLifecycle(entity.getLifecycle());
        vo.setPublishedAt(entity.getPublishedAt());
        vo.setRetractedAt(entity.getRetractedAt());
        vo.setRemark(entity.getRemark());
        vo.setCreateBy(entity.getCreateBy());
        vo.setCreateTime(entity.getCreateTime());
        return vo;
    }

    public int add(NotifyNoticeBo bo) {
        NotifyNotice entity = toEntity(bo);
        entity.setLifecycle("DRAFT");
        entity.setStatus("1");
        return dao.insert(entity);
    }

    public int update(NotifyNoticeBo bo) {
        NotifyNotice current = requireLocked(bo.getNoticeId());
        requireEditable(current);
        NotifyNotice entity = toEntity(bo);
        entity.setLifecycle(current.getLifecycle());
        entity.setStatus(current.getStatus());
        entity.setPublishedAt(current.getPublishedAt());
        entity.setRetractedAt(current.getRetractedAt());
        return dao.update(entity);
    }

    private NotifyNotice toEntity(NotifyNoticeBo bo) {
        var audience = NoticeAudiencePolicy.normalize(bo.getRecipientType(), bo.getRecipientIds(), bo.getUserTypeIds(), bo.getChannels());
        // 草稿也验证目录权限，不能绕过候选查询把越权目标写入草稿。
        if ("USER".equals(audience.recipientType())) userService.selectNotificationUsers(audience.recipientIds());
        if ("USER_TYPE".equals(audience.recipientType())) userService.selectUsersByUserTypeIds(audience.userTypeIds());
        NotifyNotice entity = new NotifyNotice();
        entity.setNoticeId(bo.getNoticeId());
        entity.setNoticeTitle(bo.getNoticeTitle());
        entity.setNoticeType(bo.getNoticeType());
        entity.setNoticeContent(bo.getNoticeContent());
        entity.setRecipientType(audience.recipientType());
        entity.setRecipientIdsJson(JsonUtils.toJsonString(audience.recipientIds()));
        entity.setUserTypeIdsJson(JsonUtils.toJsonString(audience.userTypeIds()));
        entity.setChannelsJson(JsonUtils.toJsonString(audience.channels()));
        entity.setRemark(bo.getRemark());
        return entity;
    }

    public int delete(Long[] ids) {
        if (ids == null || ids.length == 0 || Arrays.stream(ids).anyMatch(id -> id == null || id <= 0)) throw new ServiceException("通知编号不能为空且必须为正数");
        // 固定加锁顺序，批量操作不会与其他删除请求形成反向锁顺序。
        List<Long> ordered = Arrays.stream(ids).distinct().sorted().toList();
        ordered.forEach(id -> requireEditable(requireLocked(id)));
        return dao.deleteBatch(ordered);
    }

    /** 返回 null 表示此版本已经发布，调用方不再创建投递任务。 */
    public NotifyNotice publish(Long id) {
        NotifyNotice entity = requireLocked(id);
        if ("PUBLISHED".equals(entity.getLifecycle())) return null;
        requireEditable(entity);
        entity.setStatus("0");
        entity.setLifecycle("PUBLISHED");
        entity.setPublishedAt(LocalDateTime.now());
        entity.setRetractedAt(null);
        dao.update(entity);
        return entity;
    }

    public NotifyNotice retract(Long id) {
        NotifyNotice entity = requireLocked(id);
        if ("RETRACTED".equals(entity.getLifecycle())) return entity;
        if (!"PUBLISHED".equals(entity.getLifecycle())) throw new ServiceException("仅已发布通知允许撤回");
        entity.setLifecycle("RETRACTED");
        entity.setRetractedAt(LocalDateTime.now());
        dao.update(entity);
        return entity;
    }

    private NotifyNotice requireLocked(Long id) {
        if (id == null || id <= 0) throw new ServiceException("通知编号必须为正数");
        NotifyNotice entity = dao.findForUpdate(id);
        if (entity == null) throw new ServiceException("通知不存在");
        return entity;
    }

    private void requireEditable(NotifyNotice entity) {
        if (!"DRAFT".equals(entity.getLifecycle()) && !"RETRACTED".equals(entity.getLifecycle())) {
            throw new ServiceException("仅草稿或已撤回通知允许编辑、发布或删除");
        }
    }
}

package org.namewta.notify.service;

import lombok.RequiredArgsConstructor;
import org.namewta.common.json.utils.JsonUtils;
import org.namewta.common.mybatis.utils.IdGeneratorUtil;
import org.namewta.notify.api.*;
import org.namewta.notify.domain.entity.NotifyNotice;
import org.namewta.notify.domain.entity.NotifyNoticeSnapshot;
import org.namewta.notify.dao.NotifyPersistenceDao;
import org.namewta.notify.domain.policy.NoticeAudiencePolicy;
import org.namewta.common.core.exception.ServiceException;
import org.namewta.system.api.UserService;
import org.springframework.stereotype.Service;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/** 发布时冻结目录解析结果，提交唯一版本的内容与渠道投递快照。 */
@Service
@RequiredArgsConstructor
public class NotifyNoticePublisherService {
    private final NotificationApplicationService notificationService;
    private final NotifyPersistenceDao dao;
    private final UserService userService;

    public void publish(NotifyNotice notice) {
        var audience = NoticeAudiencePolicy.normalize(notice.getRecipientType(),
            JsonUtils.parseArray(notice.getRecipientIdsJson(), Long.class),
            JsonUtils.parseArray(notice.getUserTypeIdsJson(), Long.class),
            notice.getChannelsJson() == null ? null : JsonUtils.parseArray(notice.getChannelsJson(), String.class));
        List<Long> recipientIds = switch (audience.recipientType()) {
            case "ALL" -> List.of();
            case "USER" -> userService.selectNotificationUsers(audience.recipientIds()).stream().map(user -> user.getUserId()).distinct().toList();
            case "USER_TYPE" -> userService.selectUsersByUserTypeIds(audience.userTypeIds()).stream().map(user -> user.getUserId()).distinct().toList();
            default -> throw new ServiceException("发送对象类型不合法");
        };
        String recipientType = "ALL".equals(audience.recipientType()) ? "ALL" : "USER";
        if ("USER".equals(recipientType) && recipientIds.isEmpty()) throw new ServiceException("所选范围没有可接收通知的正常用户");
        List<NotificationChannel> channels = audience.channels().stream().map(NotificationChannel::valueOf).toList();
        NotifyNoticeSnapshot current = dao.latestSnapshot(notice.getNoticeId());
        int version = current == null || current.getSnapshotVersion() == null ? 1 : current.getSnapshotVersion() + 1;
        NotifyNoticeSnapshot snapshot = new NotifyNoticeSnapshot();
        snapshot.setSnapshotId(IdGeneratorUtil.nextLongId());
        snapshot.setNoticeId(notice.getNoticeId());
        snapshot.setSnapshotVersion(version);
        snapshot.setTitleSnapshot(notice.getNoticeTitle());
        snapshot.setContentSnapshot(notice.getNoticeContent());
        snapshot.setNoticeType(notice.getNoticeType());
        snapshot.setPathSnapshot("/notify/notice?noticeId=" + notice.getNoticeId());
        snapshot.setPublishedAt(notice.getPublishedAt());
        snapshot.setCreateTime(notice.getPublishedAt());
        dao.insertSnapshot(snapshot);
        Map<String, Object> params = new HashMap<>();
        params.put("title", Objects.toString(notice.getNoticeTitle(), ""));
        params.put("content", Objects.toString(notice.getNoticeContent(), ""));
        params.put("path", snapshot.getPathSnapshot());
        params.put("noticeType", notice.getNoticeType());
        params.put("channels", audience.channels());
        notificationService.submit(new NotificationCommand("notify", "notice-published", "NOTICE_PUBLISHED",
            String.valueOf(notice.getNoticeId()), recipientType, recipientIds.stream().map(String::valueOf).toList(), "notice-published", params,
            channels,
            NotificationStrategy.ALL, NotificationMode.ASYNC, 50, null, null,
            "notice-published:" + notice.getNoticeId() + ":" + version, Map.of("audit", "NOTICE_SNAPSHOT")));
    }

}

package org.namewta.notify.service;

import cn.hutool.extra.mail.MailAccount;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.namewta.common.core.domain.PageResult;
import org.namewta.common.core.exception.ServiceException;
import org.namewta.common.json.utils.JsonUtils;
import org.namewta.common.mail.notify.MailAccountResolver;
import org.namewta.common.mybatis.utils.IdGeneratorUtil;
import org.namewta.notify.dao.NotifyConfigDao;
import org.namewta.notify.domain.bo.NotifyChannelAccountBo;
import org.namewta.notify.domain.bo.NotifySceneBindingBo;
import org.namewta.notify.domain.entity.NotifyChannelAccount;
import org.namewta.notify.domain.entity.NotifySceneBinding;
import org.namewta.notify.domain.vo.NotifyChannelAccountVo;
import org.namewta.notify.domain.vo.NotifySceneBindingVo;
import org.namewta.notify.domain.vo.NotifySceneVariableVo;
import org.namewta.notify.port.SmsBlendRegistryPort;
import org.namewta.notify.support.NotifySceneCatalog;
import org.namewta.notify.support.NotifyTemplateRenderer;
import org.springframework.stereotype.Service;

import jakarta.annotation.PostConstruct;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * 通知渠道配置规则：账号、绑定、变量契约与 SMTP 解析。
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class NotifyConfigService implements MailAccountResolver {

    private final NotifyConfigDao dao;
    private final SmsBlendRegistryPort smsBlendRegistry;

    /**
     * 启动时把已启用短信账号注册进 SMS4J。
     *
     * <p>已有库尚未建表时查询会失败。缺表不得阻止进程启动；发送路径仍按无绑定失败关闭。</p>
     */
    @PostConstruct
    public void loadEnabledSmsAccounts() {
        List<NotifyChannelAccount> accounts;
        try {
            accounts = dao.listAccounts("SMS");
        } catch (RuntimeException exception) {
            log.warn("加载短信渠道账号失败，进程继续启动；发送将失败关闭。原因={}", exception.getMessage());
            return;
        }
        for (NotifyChannelAccount account : accounts) {
            registerSms(account);
        }
    }

    /**
     * 分页查询账号。
     *
     * @param channel  渠道
     * @param pageNum  页码
     * @param pageSize 页大小
     * @return 账号分页
     */
    public PageResult<NotifyChannelAccountVo> pageAccounts(String channel, Integer pageNum, Integer pageSize) {
        var page = dao.pageAccounts(channel, pageNum, pageSize);
        return PageResult.build(page.getRows().stream().map(this::toAccountVo).toList(), page.getTotal());
    }

    /**
     * 查询账号详情。
     *
     * @param accountId 主键
     * @return 账号
     */
    public NotifyChannelAccountVo getAccount(Long accountId) {
        NotifyChannelAccount account = dao.findAccount(accountId);
        if (account == null) {
            throw new ServiceException("渠道账号不存在");
        }
        return toAccountVo(account);
    }

    /**
     * 新增账号。
     *
     * @param bo 写入参数
     * @return 影响行数
     */
    public int addAccount(NotifyChannelAccountBo bo) {
        validateChannel(bo.getChannel());
        if (dao.findAccount(bo.getChannel(), bo.getConfigKey()) != null) {
            throw new ServiceException("配置标识已存在");
        }
        NotifyChannelAccount entity = toAccountEntity(bo);
        entity.setAccountId(IdGeneratorUtil.nextLongId());
        if (isBlank(entity.getEnabled())) {
            entity.setEnabled("N");
        }
        if (entity.getMinuteMax() == null || entity.getMinuteMax() < 1) {
            throw new ServiceException("账号每分钟上限必须大于 0");
        }
        validateEnabledCredentials(entity);
        int rows = dao.insert(entity);
        registerSms(entity);
        return rows;
    }

    /**
     * 更新账号。
     *
     * @param bo 写入参数
     * @return 影响行数
     */
    public int updateAccount(NotifyChannelAccountBo bo) {
        NotifyChannelAccount current = requireAccount(bo.getAccountId());
        validateChannel(bo.getChannel());
        if (!current.getChannel().equals(bo.getChannel()) || !current.getConfigKey().equals(bo.getConfigKey())) {
            NotifyChannelAccount clash = dao.findAccount(bo.getChannel(), bo.getConfigKey());
            if (clash != null && !clash.getAccountId().equals(current.getAccountId())) {
                throw new ServiceException("配置标识已存在");
            }
        }
        NotifyChannelAccount entity = toAccountEntity(bo);
        entity.setAccountId(current.getAccountId());
        if (isBlank(entity.getMailPass())) {
            entity.setMailPass(current.getMailPass());
        }
        if (isBlank(entity.getAccessKeySecret())) {
            entity.setAccessKeySecret(current.getAccessKeySecret());
        }
        if (entity.getMinuteMax() == null || entity.getMinuteMax() < 1) {
            throw new ServiceException("账号每分钟上限必须大于 0");
        }
        validateEnabledCredentials(entity);
        int rows = dao.update(entity);
        registerSms(dao.findAccount(entity.getAccountId()));
        return rows;
    }

    /**
     * 启停账号。
     *
     * @param accountId 主键
     * @param enabled   Y/N
     * @return 影响行数
     */
    public int changeStatus(Long accountId, String enabled) {
        if (!"Y".equals(enabled) && !"N".equals(enabled)) {
            throw new ServiceException("启用状态无效");
        }
        NotifyChannelAccount current = requireAccount(accountId);
        current.setEnabled(enabled);
        validateEnabledCredentials(current);
        int rows = dao.update(current);
        registerSms(current);
        return rows;
    }

    /**
     * 删除账号。
     *
     * @param accountId 主键
     * @return 影响行数
     */
    public int removeAccount(Long accountId) {
        NotifyChannelAccount current = requireAccount(accountId);
        if (dao.countBindings(accountId) > 0) {
            throw new ServiceException("账号仍被场景绑定，不能删除");
        }
        int rows = dao.deleteAccount(accountId);
        if ("SMS".equals(current.getChannel())) {
            smsBlendRegistry.remove(current.getConfigKey());
        }
        return rows;
    }

    /**
     * 列出播种场景及绑定。
     *
     * @param channel 渠道
     * @return 场景绑定
     */
    public List<NotifySceneBindingVo> listScenes(String channel) {
        validateChannel(channel);
        List<NotifySceneBindingVo> rows = new ArrayList<>();
        for (String sceneCode : NotifySceneCatalog.sceneCodes()) {
            NotifySceneBinding binding = dao.findBinding(sceneCode, channel);
            rows.add(toSceneVo(sceneCode, channel, binding));
        }
        return rows;
    }

    /**
     * 保存场景绑定。
     *
     * @param bo 绑定参数
     * @return 影响行数
     */
    public int saveBinding(NotifySceneBindingBo bo) {
        if (!NotifySceneCatalog.sceneCodes().contains(bo.getSceneCode())) {
            throw new ServiceException("未知逻辑场景");
        }
        validateChannel(bo.getChannel());
        NotifyChannelAccount account = null;
        int templateMax = bo.getTemplateMinuteMax() == null ? 60 : bo.getTemplateMinuteMax();
        if (bo.getAccountId() != null) {
            account = requireAccount(bo.getAccountId());
            if (!bo.getChannel().equals(account.getChannel())) {
                throw new ServiceException("账号渠道与绑定渠道不一致");
            }
            if (!"Y".equals(account.getEnabled())) {
                throw new ServiceException("只能绑定已启用的渠道账号");
            }
            templateMax = bo.getTemplateMinuteMax() == null ? account.getMinuteMax() : bo.getTemplateMinuteMax();
            if (templateMax > account.getMinuteMax()) {
                throw new ServiceException("模板每分钟上限不能超过账号上限");
            }
        }
        List<String> allowed = NotifySceneCatalog.variables(bo.getSceneCode()).stream()
            .map(NotifySceneCatalog.Variable::name).toList();
        List<String> required = NotifySceneCatalog.requiredNames(bo.getSceneCode());
        if ("MAIL".equals(bo.getChannel())) {
            boolean boundOrFilled = account != null
                || !isBlank(bo.getMailSubject())
                || !isBlank(bo.getMailBody());
            if (boundOrFilled) {
                NotifyTemplateRenderer.validate(nvl(bo.getMailSubject()) + nvl(bo.getMailBody()), allowed, required);
            }
        } else {
            Map<String, String> mapping = bo.getSmsParamMapping() == null ? Map.of() : bo.getSmsParamMapping();
            if (isBlank(bo.getSmsTemplateCode()) && bo.getAccountId() != null) {
                throw new ServiceException("短信供应商模板码不能为空");
            }
            for (String name : required) {
                if (bo.getAccountId() != null && (!mapping.containsKey(name) || isBlank(mapping.get(name)))) {
                    throw new ServiceException("缺少短信变量映射 " + name);
                }
            }
            for (String name : mapping.keySet()) {
                if (!allowed.contains(name)) {
                    throw new ServiceException("不允许映射未声明变量 " + name);
                }
            }
        }
        NotifySceneBinding current = dao.findBinding(bo.getSceneCode(), bo.getChannel());
        NotifySceneBinding entity = new NotifySceneBinding();
        entity.setSceneCode(bo.getSceneCode());
        entity.setChannel(bo.getChannel());
        entity.setAccountId(bo.getAccountId());
        entity.setMailSubject(nvl(bo.getMailSubject()));
        entity.setMailBody(nvl(bo.getMailBody()));
        entity.setSmsTemplateCode(nvl(bo.getSmsTemplateCode()));
        entity.setSmsParamMappingJson(JsonUtils.toJsonString(
            bo.getSmsParamMapping() == null ? Map.of() : bo.getSmsParamMapping()));
        entity.setTemplateMinuteMax(templateMax);
        entity.setRestricted(isBlank(bo.getRestricted()) ? "N" : bo.getRestricted());
        entity.setRecipientMinuteMax(bo.getRecipientMinuteMax() == null ? 0 : bo.getRecipientMinuteMax());
        entity.setRecipientDayMax(bo.getRecipientDayMax() == null ? 0 : bo.getRecipientDayMax());
        if (current == null) {
            entity.setBindingId(IdGeneratorUtil.nextLongId());
            return dao.insert(entity);
        }
        entity.setBindingId(current.getBindingId());
        return dao.update(entity);
    }

    /**
     * 按 configKey 解析 SMTP 账户。
     *
     * @param providerKey 账号标识
     * @return SMTP 账户
     */
    @Override
    public MailAccount resolve(String providerKey) {
        if (isBlank(providerKey)) {
            return null;
        }
        NotifyChannelAccount account = dao.findAccount("MAIL", providerKey);
        if (account == null || !"Y".equals(account.getEnabled())) {
            return null;
        }
        MailAccount mailAccount = new MailAccount();
        mailAccount.setHost(account.getHost());
        mailAccount.setPort(account.getPort());
        mailAccount.setFrom(account.getMailFrom());
        mailAccount.setUser(account.getMailUser());
        mailAccount.setPass(account.getMailPass());
        mailAccount.setAuth(true);
        mailAccount.setSslEnable("Y".equals(account.getSslEnable()));
        mailAccount.setStarttlsEnable("Y".equals(account.getStarttlsEnable()));
        return mailAccount;
    }

    private void registerSms(NotifyChannelAccount account) {
        if (account == null || !"SMS".equals(account.getChannel()) || isBlank(account.getConfigKey())) {
            return;
        }
        if ("Y".equals(account.getEnabled())) {
            smsBlendRegistry.upsert(account);
        } else {
            smsBlendRegistry.remove(account.getConfigKey());
        }
    }

    private NotifyChannelAccount requireAccount(Long accountId) {
        NotifyChannelAccount account = dao.findAccount(accountId);
        if (account == null) {
            throw new ServiceException("渠道账号不存在");
        }
        return account;
    }

    private void validateChannel(String channel) {
        if (!"MAIL".equals(channel) && !"SMS".equals(channel)) {
            throw new ServiceException("渠道仅支持 MAIL 或 SMS");
        }
    }

    /**
     * 启用中的账号必须已具备渠道密钥与连接字段，避免把失败推迟到供应商。
     *
     * @param account 账号
     */
    private void validateEnabledCredentials(NotifyChannelAccount account) {
        if (account == null || !"Y".equals(account.getEnabled())) {
            return;
        }
        if ("MAIL".equals(account.getChannel())) {
            if (isBlank(account.getHost()) || account.getPort() == null
                || isBlank(account.getMailFrom()) || isBlank(account.getMailPass())) {
                throw new ServiceException("启用邮件账号必须填写 SMTP 主机、端口、发件人和密码");
            }
            return;
        }
        if (isBlank(account.getSupplier()) || isBlank(account.getAccessKeyId()) || isBlank(account.getAccessKeySecret())) {
            throw new ServiceException("启用短信账号必须填写厂商、AccessKey 和密钥");
        }
    }

    private NotifyChannelAccount toAccountEntity(NotifyChannelAccountBo bo) {
        NotifyChannelAccount entity = new NotifyChannelAccount();
        entity.setChannel(bo.getChannel());
        entity.setConfigKey(bo.getConfigKey());
        entity.setEnabled(bo.getEnabled());
        entity.setSupplier(bo.getSupplier());
        entity.setHost(bo.getHost());
        entity.setPort(bo.getPort());
        entity.setMailFrom(bo.getMailFrom());
        entity.setMailUser(bo.getMailUser());
        entity.setMailPass(bo.getMailPass());
        entity.setSslEnable(bo.getSslEnable());
        entity.setStarttlsEnable(bo.getStarttlsEnable());
        entity.setAccessKeyId(bo.getAccessKeyId());
        entity.setAccessKeySecret(bo.getAccessKeySecret());
        entity.setSignature(bo.getSignature());
        entity.setSdkAppId(bo.getSdkAppId());
        entity.setMinuteMax(bo.getMinuteMax());
        entity.setRemark(bo.getRemark());
        return entity;
    }

    private NotifyChannelAccountVo toAccountVo(NotifyChannelAccount entity) {
        NotifyChannelAccountVo vo = new NotifyChannelAccountVo();
        vo.setAccountId(entity.getAccountId());
        vo.setChannel(entity.getChannel());
        vo.setConfigKey(entity.getConfigKey());
        vo.setEnabled(entity.getEnabled());
        vo.setSupplier(entity.getSupplier());
        vo.setHost(entity.getHost());
        vo.setPort(entity.getPort());
        vo.setMailFrom(entity.getMailFrom());
        vo.setMailUser(entity.getMailUser());
        vo.setMailPassSet(!isBlank(entity.getMailPass()));
        vo.setSslEnable(entity.getSslEnable());
        vo.setStarttlsEnable(entity.getStarttlsEnable());
        vo.setAccessKeyId(entity.getAccessKeyId());
        vo.setAccessKeySecretSet(!isBlank(entity.getAccessKeySecret()));
        vo.setSignature(entity.getSignature());
        vo.setSdkAppId(entity.getSdkAppId());
        vo.setMinuteMax(entity.getMinuteMax());
        vo.setRemark(entity.getRemark());
        vo.setUpdateTime(entity.getUpdateTime());
        return vo;
    }

    private NotifySceneBindingVo toSceneVo(String sceneCode, String channel, NotifySceneBinding binding) {
        NotifySceneBindingVo vo = new NotifySceneBindingVo();
        vo.setSceneCode(sceneCode);
        vo.setTitle(NotifySceneCatalog.title(sceneCode));
        vo.setVariables(NotifySceneCatalog.variables(sceneCode).stream().map(variable -> {
            NotifySceneVariableVo item = new NotifySceneVariableVo();
            item.setName(variable.name());
            item.setRequired(variable.required());
            item.setExample(variable.example());
            item.setDescription(variable.description());
            return item;
        }).toList());
        vo.setChannel(channel);
        if (binding == null) {
            return vo;
        }
        vo.setBindingId(binding.getBindingId());
        vo.setAccountId(binding.getAccountId());
        if (binding.getAccountId() != null) {
            NotifyChannelAccount account = dao.findAccount(binding.getAccountId());
            if (account != null) {
                vo.setAccountConfigKey(account.getConfigKey());
                vo.setAccountEnabled(account.getEnabled());
            }
        }
        vo.setMailSubject(binding.getMailSubject());
        vo.setMailBody(binding.getMailBody());
        vo.setSmsTemplateCode(binding.getSmsTemplateCode());
        var mapping = JsonUtils.parseMap(binding.getSmsParamMappingJson());
        vo.setSmsParamMapping(mapping == null ? Map.of() : mapping.entrySet().stream()
            .collect(java.util.stream.Collectors.toMap(Map.Entry::getKey, item -> String.valueOf(item.getValue()),
                (left, right) -> left, LinkedHashMap::new)));
        vo.setTemplateMinuteMax(binding.getTemplateMinuteMax());
        vo.setRestricted(binding.getRestricted());
        vo.setRecipientMinuteMax(binding.getRecipientMinuteMax());
        vo.setRecipientDayMax(binding.getRecipientDayMax());
        return vo;
    }

    private boolean isBlank(String value) {
        return value == null || value.isBlank();
    }

    private String nvl(String value) {
        return value == null ? "" : value;
    }
}

package org.namewta.notify.support;

import java.util.List;
import java.util.Map;

/**
 * 代码播种的逻辑场景与变量契约。
 */
public final class NotifySceneCatalog {

    private NotifySceneCatalog() {
    }

    /**
     * 播种场景编码。
     *
     * @return 场景编码列表
     */
    public static List<String> sceneCodes() {
        return List.of("auth-captcha", "person-rebind", "enterprise-transfer", "workflow-task", "notice-published");
    }

    /**
     * 场景标题。
     *
     * @param sceneCode 场景编码
     * @return 标题
     */
    public static String title(String sceneCode) {
        return switch (sceneCode) {
            case "auth-captcha" -> "登录验证码";
            case "person-rebind" -> "个人实名换绑";
            case "enterprise-transfer" -> "企业负责人转移";
            case "workflow-task" -> "工作流待办";
            case "notice-published" -> "公告发布";
            default -> sceneCode;
        };
    }

    /**
     * 场景变量。
     *
     * @param sceneCode 场景编码
     * @return 变量列表
     */
    public static List<Variable> variables(String sceneCode) {
        return switch (sceneCode) {
            case "auth-captcha" -> List.of(
                new Variable("code", true, "1234", "验证码"),
                new Variable("expireMinutes", true, "5", "有效分钟数"));
            case "person-rebind" -> List.of();
            case "enterprise-transfer" -> List.of(new Variable("code", true, "123456", "转移验证码"));
            case "workflow-task", "notice-published" -> List.of(
                new Variable("title", true, "标题", "业务标题"),
                new Variable("content", true, "正文", "业务正文"),
                new Variable("path", true, "/task", "跳转路径"));
            default -> List.of();
        };
    }

    /**
     * 必填变量名。
     *
     * @param sceneCode 场景编码
     * @return 必填变量
     */
    public static List<String> requiredNames(String sceneCode) {
        return variables(sceneCode).stream().filter(Variable::required).map(Variable::name).toList();
    }

    /**
     * 样例变量。
     *
     * @param sceneCode 场景编码
     * @return 样例
     */
    public static Map<String, String> examples(String sceneCode) {
        return variables(sceneCode).stream().collect(java.util.stream.Collectors.toMap(Variable::name, Variable::example));
    }

    /**
     * 场景变量定义。
     *
     * @param name        变量名
     * @param required    是否必填
     * @param example     样例
     * @param description 说明
     */
    public record Variable(String name, boolean required, String example, String description) {
    }
}

package org.namewta.notify.support;

import org.namewta.common.json.utils.JsonUtils;
import org.namewta.notify.domain.entity.NotifyChannelAccount;
import org.namewta.notify.domain.entity.NotifySceneBinding;
import org.namewta.notify.port.NotifyQuotaPort;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Duration;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * 解析场景绑定、渲染文案并检查三层限额。不依赖渠道 SPI 类型。
 */
public final class NotifySendPlanner {

    private NotifySendPlanner() {
    }

    /**
     * 发送计划。
     *
     * @param ok              是否可发送
     * @param errorCode       失败码
     * @param errorMessage    失败说明
     * @param providerKey     账号标识
     * @param mail            是否邮件
     * @param subject         邮件主题
     * @param body            邮件正文
     * @param html            是否 HTML
     * @param smsTemplateCode 短信模板码
     * @param smsParams       短信参数
     */
    public record Plan(boolean ok, String errorCode, String errorMessage, String providerKey, boolean mail,
                       String subject, String body, boolean html, String smsTemplateCode,
                       Map<String, String> smsParams) {
        public static Plan fail(String code, String message) {
            return new Plan(false, code, message, null, false, null, null, false, null, Map.of());
        }
    }

    /**
     * 生成 MAIL/SMS 发送计划。
     *
     * @param sceneCode 场景
     * @param channel   渠道
     * @param target    收件人
     * @param params    变量
     * @param binding   绑定
     * @param account   账号
     * @param quotaPort 限额
     * @return 计划
     */
    public static Plan plan(String sceneCode, String channel, String target, Map<String, String> params,
                            NotifySceneBinding binding, NotifyChannelAccount account, NotifyQuotaPort quotaPort) {
        if (binding == null || binding.getAccountId() == null) {
            return Plan.fail("UNBOUND_CHANNEL", "场景未绑定渠道账号");
        }
        if (account == null || !"Y".equals(account.getEnabled())) {
            return Plan.fail("ACCOUNT_DISABLED", "渠道账号未启用或不存在");
        }
        if (!channel.equals(account.getChannel())) {
            return Plan.fail("ACCOUNT_CHANNEL_MISMATCH", "绑定账号渠道不匹配");
        }
        List<String> required = NotifySceneCatalog.requiredNames(sceneCode);
        for (String name : required) {
            if (params == null || params.get(name) == null || params.get(name).isBlank()) {
                return Plan.fail("MISSING_VARIABLE", "缺少必填变量 " + name);
            }
        }
        if ("MAIL".equals(channel)) {
            String subject = NotifyTemplateRenderer.render(binding.getMailSubject(), params);
            String body = NotifyTemplateRenderer.render(binding.getMailBody(), params);
            return finish(account, binding, sceneCode, channel, target, quotaPort, true, subject, body,
                body != null && body.contains("<"), null, Map.of());
        }
        if (binding.getSmsTemplateCode() == null || binding.getSmsTemplateCode().isBlank()) {
            return Plan.fail("SMS_TEMPLATE_MISSING", "未配置短信供应商模板码");
        }
        Map<String, String> mapping = mapping(binding.getSmsParamMappingJson());
        Map<String, String> providerParams = new LinkedHashMap<>();
        mapping.forEach((logical, providerName) -> {
            if (params != null) {
                providerParams.put(providerName, params.getOrDefault(logical, ""));
            }
        });
        return finish(account, binding, sceneCode, channel, target, quotaPort, false, null, null, false,
            binding.getSmsTemplateCode(), providerParams);
    }

    private static Plan finish(NotifyChannelAccount account, NotifySceneBinding binding, String sceneCode,
                               String channel, String target, NotifyQuotaPort quotaPort, boolean mail,
                               String subject, String body, boolean html, String smsTemplateCode,
                               Map<String, String> smsParams) {
        List<String> held = new ArrayList<>();
        if (!acquireQuota(quotaPort, held, "acct:" + account.getAccountId(), account.getMinuteMax(), Duration.ofMinutes(1))) {
            return Plan.fail("ACCOUNT_QUOTA", "账号每分钟发送上限已用尽");
        }
        int templateMax = binding.getTemplateMinuteMax() == null ? account.getMinuteMax() : binding.getTemplateMinuteMax();
        if (!acquireQuota(quotaPort, held, "tpl:" + sceneCode + ":" + channel, templateMax, Duration.ofMinutes(1))) {
            releaseHeld(quotaPort, held);
            return Plan.fail("TEMPLATE_QUOTA", "模板每分钟发送上限已用尽");
        }
        if ("Y".equals(binding.getRestricted()) && target != null && !target.isBlank()) {
            int minute = binding.getRecipientMinuteMax() == null ? 0 : binding.getRecipientMinuteMax();
            int day = binding.getRecipientDayMax() == null ? 0 : binding.getRecipientDayMax();
            String safeTarget = recipientQuotaToken(target);
            if (!acquireQuota(quotaPort, held, "rcpt-m:" + sceneCode + ":" + channel + ":" + safeTarget, minute, Duration.ofMinutes(1))) {
                releaseHeld(quotaPort, held);
                return Plan.fail("RECIPIENT_MINUTE_QUOTA", "收件人每分钟拦截上限已用尽");
            }
            if (!acquireQuota(quotaPort, held, "rcpt-d:" + sceneCode + ":" + channel + ":" + safeTarget + ":"
                + LocalDate.now().format(DateTimeFormatter.BASIC_ISO_DATE), day, Duration.ofDays(1))) {
                releaseHeld(quotaPort, held);
                return Plan.fail("RECIPIENT_DAY_QUOTA", "收件人每天拦截上限已用尽");
            }
        }
        return new Plan(true, null, null, account.getConfigKey(), mail, subject, body, html, smsTemplateCode, smsParams);
    }

    /**
     * 收件人限额键：规范化后取 SHA-256 前 16 个十六进制字符，避免 hashCode 碰撞与跨 JVM 不稳定。
     *
     * @param target 邮箱或手机号
     * @return 稳定摘要
     */
    public static String recipientQuotaToken(String target) {
        String normalized = target == null ? "" : target.trim().toLowerCase(Locale.ROOT).replaceAll("\\s+", "");
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(normalized.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(16);
            for (int i = 0; i < 8; i++) {
                hex.append(String.format("%02x", digest[i] & 0xff));
            }
            return hex.toString();
        } catch (NoSuchAlgorithmException exception) {
            throw new IllegalStateException("SHA-256 is unavailable", exception);
        }
    }

    private static boolean acquireQuota(NotifyQuotaPort quotaPort, List<String> held, String key, int limit, Duration window) {
        if (quotaPort == null || limit <= 0) {
            return true;
        }
        if (!quotaPort.tryAcquire(key, limit, window)) {
            return false;
        }
        held.add(key);
        return true;
    }

    private static void releaseHeld(NotifyQuotaPort quotaPort, List<String> held) {
        if (quotaPort == null) {
            return;
        }
        for (int i = held.size() - 1; i >= 0; i--) {
            quotaPort.release(held.get(i));
        }
        held.clear();
    }

    private static Map<String, String> mapping(String json) {
        var parsed = JsonUtils.parseMap(json);
        if (parsed == null) {
            return Map.of();
        }
        Map<String, String> mapping = new LinkedHashMap<>();
        parsed.forEach((key, value) -> mapping.put(key, value == null ? "" : String.valueOf(value)));
        return mapping;
    }
}

package org.namewta.notify.support;

import org.namewta.common.core.exception.ServiceException;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * 邮件模板变量占用位置校验与渲染。
 */
public final class NotifyTemplateRenderer {

    private static final Pattern TOKEN = Pattern.compile("\\$\\{([A-Za-z][A-Za-z0-9_]*)}");

    private NotifyTemplateRenderer() {
    }

    /**
     * 校验模板只使用已声明变量，且包含全部必填变量。
     *
     * @param template      主题或正文
     * @param allowed       允许的变量名
     * @param requiredNames 必填变量名
     */
    public static void validate(String template, List<String> allowed, List<String> requiredNames) {
        String text = template == null ? "" : template;
        List<String> used = tokens(text);
        for (String name : used) {
            if (!allowed.contains(name)) {
                throw new ServiceException("不允许使用未声明变量 ${" + name + "}");
            }
        }
        for (String required : requiredNames) {
            if (!used.contains(required)) {
                throw new ServiceException("缺少必填变量 ${" + required + "}");
            }
        }
    }

    /**
     * 用变量值替换 token。
     *
     * @param template 模板
     * @param params   变量
     * @return 渲染结果
     */
    public static String render(String template, Map<String, String> params) {
        if (template == null) {
            return "";
        }
        Map<String, String> values = params == null ? Map.of() : params;
        Matcher matcher = TOKEN.matcher(template);
        StringBuilder out = new StringBuilder();
        while (matcher.find()) {
            String value = values.getOrDefault(matcher.group(1), "");
            matcher.appendReplacement(out, Matcher.quoteReplacement(value == null ? "" : value));
        }
        matcher.appendTail(out);
        return out.toString();
    }

    /**
     * 提取模板中的变量名。
     *
     * @param template 模板
     * @return 变量名
     */
    public static List<String> tokens(String template) {
        List<String> names = new ArrayList<>();
        Matcher matcher = TOKEN.matcher(template == null ? "" : template);
        while (matcher.find()) {
            String name = matcher.group(1);
            if (!names.contains(name)) {
                names.add(name);
            }
        }
        return names;
    }

    /**
     * 将任意模板参数转为字符串映射。
     *
     * @param raw 原始参数
     * @return 字符串参数
     */
    public static Map<String, String> stringify(Map<String, ?> raw) {
        Map<String, String> values = new LinkedHashMap<>();
        if (raw == null) {
            return values;
        }
        raw.forEach((key, value) -> values.put(key, value == null ? "" : String.valueOf(value)));
        return values;
    }
}

package org.namewta.notify.dao;

import lombok.RequiredArgsConstructor;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import org.namewta.common.core.domain.PageResult;
import org.namewta.common.mybatis.core.page.PageQuery;
import org.namewta.notify.domain.bo.NotifyNoticeBo;
import org.namewta.notify.domain.entity.NotifyNotice;
import org.namewta.notify.mapper.NotifyNoticeMapper;
import org.namewta.notify.domain.entity.NotifyNoticeSnapshot;
import org.namewta.notify.mapper.NotifyNoticeSnapshotMapper;
import org.springframework.stereotype.Repository;

/** 通知模块统一持久化边界，复杂查询继续下沉到 Mapper/XML。 */
@Repository
@RequiredArgsConstructor
public class NotifyPersistenceDao {
    private final NotifyNoticeMapper noticeMapper;
    private final NotifyNoticeSnapshotMapper snapshotMapper;

    /** 每次查询新建 Wrapper，分页与排序仅在持久化边界处理。 */
    public PageResult<NotifyNotice> page(NotifyNoticeBo query, Integer pageNum, Integer pageSize) {
        var wrapper = new LambdaQueryWrapper<NotifyNotice>()
            .like(query.getNoticeTitle() != null && !query.getNoticeTitle().isBlank(), NotifyNotice::getNoticeTitle, query.getNoticeTitle())
            .eq(query.getNoticeType() != null && !query.getNoticeType().isBlank(), NotifyNotice::getNoticeType, query.getNoticeType())
            .eq(query.getStatus() != null && !query.getStatus().isBlank(), NotifyNotice::getStatus, query.getStatus())
            .orderByDesc(NotifyNotice::getCreateTime).orderByDesc(NotifyNotice::getNoticeId);
        var page = noticeMapper.selectPage(new PageQuery(pageSize, pageNum).build(), wrapper);
        return PageResult.build(page.getRecords(), page.getTotal());
    }

    public NotifyNotice find(Long noticeId) { return noticeId == null ? null : noticeMapper.selectById(noticeId); }
    public NotifyNotice findForUpdate(Long noticeId) { return noticeId == null ? null : noticeMapper.selectByIdForUpdate(noticeId); }
    public int insert(NotifyNotice notice) { return noticeMapper.insert(notice); }
    public int update(NotifyNotice notice) { return noticeMapper.updateById(notice); }
    public int deleteBatch(java.util.Collection<Long> ids) { return noticeMapper.deleteBatchIds(ids); }
    public NotifyNoticeSnapshot latestSnapshot(Long noticeId) {
        return snapshotMapper.selectOne(new LambdaQueryWrapper<NotifyNoticeSnapshot>()
            .eq(NotifyNoticeSnapshot::getNoticeId, noticeId)
            .orderByDesc(NotifyNoticeSnapshot::getSnapshotVersion).last("limit 1"));
    }
    public int insertSnapshot(NotifyNoticeSnapshot snapshot) { return snapshotMapper.insert(snapshot); }
}

