package org.namewta.notify.domain.policy;

import java.util.Set;

/** 回调与投递完成共享的单调状态规则；人工重试由独立用例显式恢复 PENDING。 */
public final class NotificationDeliveryPolicy {
    /** 纯静态策略禁止实例化。 */
    private NotificationDeliveryPolicy() { }

    /** 终态不可被较晚的 Provider 响应或低等级回执覆盖。 */
    public static boolean canAdvance(String current, String next) {
        if (current == null || current.isBlank()) return true;
        if (Set.of("DELIVERED", "CANCELLED", "FAILED", "UNDELIVERABLE").contains(current)) return false;
        return rank(next) > rank(current);
    }

    /** 仅比较回执确定性，不将 UNKNOWN 当作送达。 */
    private static int rank(String status) {
        if (status == null) return 0;
        return switch (status) {
            case "DELIVERED" -> 4;
            case "UNDELIVERABLE", "FAILED" -> 3;
            case "ACCEPTED" -> 2;
            default -> 1;
        };
    }
}

package org.namewta.notify.domain.policy;

import org.namewta.common.core.exception.ServiceException;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;

/** 公告草稿的发送范围规则；空指定目标绝不能退化为全体用户。 */
public final class NoticeAudiencePolicy {
    private NoticeAudiencePolicy() { }

    /** 已规范化且不可变的草稿目标和渠道。 */
    public record Audience(String recipientType, List<Long> recipientIds, List<Long> userTypeIds, List<String> channels) { }

    public static Audience normalize(String type, List<Long> recipients, List<Long> userTypes, List<String> channels) {
        String normalizedType = type == null ? "ALL" : type.trim().toUpperCase(Locale.ROOT);
        List<Long> ids = normalizeIds(recipients);
        List<Long> types = normalizeIds(userTypes);
        boolean valid = switch (normalizedType) {
            case "ALL" -> ids.isEmpty() && types.isEmpty();
            case "USER" -> !ids.isEmpty() && types.isEmpty();
            case "USER_TYPE" -> ids.isEmpty() && !types.isEmpty();
            default -> false;
        };
        if (!valid) throw new ServiceException("发送对象类型与所选目标不匹配，指定用户或用户类型不能为空");
        List<String> normalizedChannels = channels == null ? List.of("IN_APP") : channels;
        if (normalizedChannels.isEmpty() || normalizedChannels.stream().anyMatch(value -> value == null
            || !List.of("IN_APP", "SMS", "MAIL").contains(value.trim().toUpperCase(Locale.ROOT)))) {
            throw new ServiceException("至少选择一个已实现的渠道：站内信、短信或邮件");
        }
        return new Audience(normalizedType, ids, types, normalizedChannels.stream()
            .map(value -> value.trim().toUpperCase(Locale.ROOT)).distinct().toList());
    }

    private static List<Long> normalizeIds(List<Long> values) {
        if (values == null) return List.of();
        if (values.stream().anyMatch(id -> id == null || id <= 0)) throw new ServiceException("发送目标编号必须为正数");
        return List.copyOf(new LinkedHashSet<>(values));
    }
}

package org.namewta.notify.domain.policy;

import org.namewta.notify.api.NotificationStatus;

import java.util.List;

/**
 * 通知聚合状态策略，区分供应商接受、实际送达、失败和待回执。
 */
public final class NotificationAggregatePolicy {
    private NotificationAggregatePolicy() {
    }

    /**
     * 根据所有渠道投递状态计算通知聚合状态。
     *
     * @param statuses 投递状态
     * @return 聚合状态
     */
    public static NotificationStatus aggregate(List<String> statuses) {
        if (statuses == null || statuses.isEmpty()) return NotificationStatus.UNKNOWN;
        long cancelled = statuses.stream().filter("CANCELLED"::equals).count();
        long effective = statuses.size() - cancelled;
        if (effective == 0) return NotificationStatus.CANCELLED;
        if (statuses.stream().anyMatch(status -> "PENDING".equals(status))) return NotificationStatus.PROCESSING;
        if (statuses.stream().filter("DELIVERED"::equals).count() == effective) return NotificationStatus.DELIVERED;
        if (statuses.stream().anyMatch(status -> "UNKNOWN".equals(status) || "WAITING_RECEIPT".equals(status))) {
            return NotificationStatus.UNKNOWN;
        }
        long successful = statuses.stream().filter(status -> "ACCEPTED".equals(status) || "DELIVERED".equals(status)).count();
        long failed = statuses.stream().filter(status -> "FAILED".equals(status) || "UNDELIVERABLE".equals(status)).count();
        if (successful > 0 && failed > 0) return NotificationStatus.PARTIAL_FAILURE;
        if (successful == effective) return NotificationStatus.ACCEPTED;
        return NotificationStatus.FAILED;
    }
}

