package org.namewta.notify.adapter.provider;

import org.namewta.notify.domain.entity.NotifyChannelAccount;
import org.namewta.notify.port.SmsBlendRegistryPort;
import org.dromara.sms4j.aliyun.config.AlibabaFactory;
import org.dromara.sms4j.api.universal.SupplierConfig;
import org.dromara.sms4j.core.factory.SmsFactory;
import org.dromara.sms4j.provider.config.BaseConfig;
import org.dromara.sms4j.provider.factory.BeanFactory;
import org.dromara.sms4j.provider.factory.BaseProviderFactory;
import org.dromara.sms4j.provider.factory.ProviderFactoryHolder;
import org.dromara.sms4j.tencent.config.TencentFactory;
import org.springframework.stereotype.Component;

/**
 * 把短信渠道账号注册为 SMS4J blend。
 *
 * <p>必须实例化厂商自己的 Config（如 {@code AlibabaConfig}），不能用匿名 {@code BaseConfig} 子类，
 * 否则 {@code AlibabaFactory.createSms} 会 ClassCastException。</p>
 */
@Component
public class Sms4jBlendRegistry implements SmsBlendRegistryPort {

    static {
        ProviderFactoryHolder.registerFactory(AlibabaFactory.instance());
        ProviderFactoryHolder.registerFactory(TencentFactory.instance());
    }

    /**
     * 注册或更新。
     *
     * @param account 短信账号
     */
    @Override
    public void upsert(NotifyChannelAccount account) {
        if (account == null || account.getConfigKey() == null) {
            return;
        }
        remove(account.getConfigKey());
        BeanFactory.getSmsConfig();
        SmsFactory.createSmsBlend(vendorConfig(account));
    }

    /**
     * 按厂商标识构造 SMS4J 配置对象。
     *
     * @param account 短信账号
     * @return 厂商 Config，供 {@link SmsFactory#createSmsBlend(SupplierConfig)} 使用
     */
    public BaseConfig vendorConfig(NotifyChannelAccount account) {
        if (account == null || isBlank(account.getSupplier())) {
            throw new IllegalArgumentException("短信厂商标识不能为空");
        }
        String supplier = account.getSupplier().trim();
        BaseProviderFactory<?, ?> factory = ProviderFactoryHolder.requireForSupplier(supplier);
        if (factory == null || factory.getConfigClass() == null) {
            throw new IllegalArgumentException("不支持的短信厂商 " + supplier);
        }
        try {
            Object created = factory.getConfigClass().getDeclaredConstructor().newInstance();
            if (!(created instanceof BaseConfig config)) {
                throw new IllegalArgumentException("短信厂商配置类型无效 " + supplier);
            }
            config.setConfigId(account.getConfigKey());
            config.setAccessKeyId(account.getAccessKeyId());
            config.setAccessKeySecret(account.getAccessKeySecret());
            config.setSignature(account.getSignature());
            config.setSdkAppId(account.getSdkAppId());
            return config;
        } catch (ReflectiveOperationException exception) {
            throw new IllegalArgumentException("无法创建短信厂商配置 " + supplier, exception);
        }
    }

    /**
     * 注销。
     *
     * @param configKey 账号标识
     */
    @Override
    public void remove(String configKey) {
        if (configKey == null || configKey.isBlank()) {
            return;
        }
        try {
            SmsFactory.unregister(configKey);
        } catch (RuntimeException ignored) {
            // SmsLoad 未初始化时仍从 BLENDS 表删除；失败不影响停用语义。
        }
    }

    private boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}

package org.namewta.notify.adapter.worker;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.namewta.notify.domain.entity.NotifyOutbox;
import org.namewta.notify.port.NotifyDispatchPort;
import org.namewta.notify.port.NotifyOutboxClaimPort;
import org.namewta.notify.support.outbox.NotifyOutboxWakeSignal;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Outbox Worker：跨进程唤醒与慢速兜底共用 claim+dispatch，不按 outboxId 直投。
 */
@Slf4j
@Component
@RequiredArgsConstructor
public class NotifyOutboxWorker {

    private final NotifyOutboxClaimPort claimService;
    private final NotifyDispatchPort dispatchService;
    private final String owner = UUID.randomUUID().toString();
    private final AtomicBoolean draining = new AtomicBoolean();

    /**
     * 慢速兜底扫描。默认 60000ms，配置项名保持 {@code notify.outbox.poll-delay-ms}。
     */
    @Scheduled(fixedDelayString = "${notify.outbox.poll-delay-ms:60000}")
    public void poll() {
        drain(Trigger.POLL);
    }

    /**
     * Redis 跨进程唤醒入口。载荷中的 outboxId 只是 hint，必须再走 claim/lease。
     *
     * @param signal T-01 唤醒信号，允许为 {@code null}
     */
    public void onWake(NotifyOutboxWakeSignal signal) {
        drain(Trigger.WAKE);
    }

    /**
     * 连续领取直到本批为空。{@code trigger} 写入日志以区分唤醒与兜底。
     *
     * @param trigger 唤醒或定时兜底
     */
    void drain(Trigger trigger) {
        // 重叠信号不排队、不创建线程；最后一次空批与新信号相撞时由既有慢轮询兜底。
        if (!draining.compareAndSet(false, true)) return;
        try {
            int claimed = 0;
            int batches = 0;
            List<NotifyOutbox> batch;
            do {
                batch = claimService.claim(owner);
                for (NotifyOutbox outbox : batch) dispatchService.dispatch(outbox);
                claimed += batch.size();
                batches++;
            } while (!batch.isEmpty());
            log.info("notify outbox drain trigger={} claimed={} batches={}", trigger, claimed, batches);
        } finally {
            draining.set(false);
        }
    }

    /**
     * 领取触发来源，供日志区分唤醒与兜底 tick。
     */
    enum Trigger {
        /** 跨进程或同 JVM 唤醒。 */
        WAKE,
        /** {@code @Scheduled} 慢速兜底。 */
        POLL
    }
}

package org.namewta.notify.adapter.worker;

import lombok.extern.slf4j.Slf4j;
import org.namewta.common.redis.utils.RedisUtils;
import org.namewta.notify.support.outbox.NotifyOutboxWakeChannels;
import org.namewta.notify.support.outbox.NotifyOutboxWakeSignal;
import org.springframework.beans.factory.DisposableBean;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.InitializingBean;
import org.springframework.stereotype.Component;

import java.util.function.Consumer;

/**
 * 订阅 T-01 Redis 唤醒通道，转发到 Worker 统一 claim+dispatch 循环。
 *
 * <p>订阅失败不得阻止进程启动；空闲投递仍依赖慢速兜底。</p>
 */
@Slf4j
@Component
public class NotifyOutboxWakeSubscriber implements InitializingBean, DisposableBean {

    private final NotifyOutboxWorker worker;
    private final NotifyOutboxWakeBus bus;
    private Integer listenerId;

    /**
     * 生产构造：经 {@link RedisUtils} 订阅跨进程通道。
     *
     * @param worker 统一领取循环
     */
    @Autowired
    public NotifyOutboxWakeSubscriber(NotifyOutboxWorker worker) {
        this(worker, redisBus());
    }

    /**
     * 测试缝合点：替换 Redis 订阅而不加载客户端。
     *
     * @param worker 统一领取循环
     * @param bus    订阅适配
     */
    NotifyOutboxWakeSubscriber(NotifyOutboxWorker worker, NotifyOutboxWakeBus bus) {
        this.worker = worker;
        this.bus = bus;
    }

    /**
     * 组件启动时订阅唤醒通道。
     */
    @Override
    public void afterPropertiesSet() {
        try {
            listenerId = bus.subscribe(
                NotifyOutboxWakeChannels.REDIS_CHANNEL,
                NotifyOutboxWakeSignal.class,
                this::onMessage);
        } catch (RuntimeException ex) {
            log.warn("notify outbox wake subscribe failed, slow poll remains", ex);
        }
    }

    /**
     * 组件销毁时取消订阅。
     */
    @Override
    public void destroy() {
        if (listenerId == null) {
            return;
        }
        try {
            bus.unsubscribe(NotifyOutboxWakeChannels.REDIS_CHANNEL, listenerId);
        } catch (RuntimeException ex) {
            log.warn("notify outbox wake unsubscribe failed", ex);
        }
    }

    private void onMessage(NotifyOutboxWakeSignal signal) {
        try {
            worker.onWake(signal);
        } catch (RuntimeException ex) {
            log.warn("notify outbox wake drain failed, trigger=WAKE", ex);
        }
    }

    private static NotifyOutboxWakeBus redisBus() {
        return new NotifyOutboxWakeBus() {
            @Override
            public int subscribe(String channel, Class<NotifyOutboxWakeSignal> type,
                                 Consumer<NotifyOutboxWakeSignal> consumer) {
                return RedisUtils.subscribeAndGetListenerId(channel, type, consumer);
            }

            @Override
            public void unsubscribe(String channel, int listenerId) {
                RedisUtils.unsubscribe(channel, listenerId);
            }
        };
    }
}

/**
 * Outbox 唤醒总线。生产实现调用 {@link RedisUtils} 的 subscribe/unsubscribe。
 */
interface NotifyOutboxWakeBus {

    /**
     * 订阅通道并返回监听器 ID。
     *
     * @param channel  通道
     * @param type     载荷类型
     * @param consumer 回调
     * @return 监听器 ID
     */
    int subscribe(String channel, Class<NotifyOutboxWakeSignal> type, Consumer<NotifyOutboxWakeSignal> consumer);

    /**
     * 取消订阅。
     *
     * @param channel    通道
     * @param listenerId 监听器 ID
     */
    void unsubscribe(String channel, int listenerId);
}

package org.namewta.notify.adapter.event;

import com.baomidou.dynamic.datasource.annotation.DsTxEventListener;
import lombok.extern.slf4j.Slf4j;
import org.namewta.common.redis.utils.RedisUtils;
import org.namewta.notify.support.outbox.NotifyOutboxWakeChannels;
import org.namewta.notify.support.outbox.NotifyOutboxWakeRequestedEvent;
import org.namewta.notify.support.outbox.NotifyOutboxWakeSignal;
import org.springframework.stereotype.Component;
import org.springframework.transaction.event.TransactionPhase;

import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeoutException;

/**
 * Outbox 提交后跨进程唤醒发布器。
 *
 * <p>Redis pub/sub 是唯一唤醒路径；提交线程最多等待发布确认 250ms，不调用 Worker。失败由慢轮询恢复。</p>
 */
@Slf4j
@Component
public class NotifyOutboxWakePublisher {

    private static final long PUBLISH_TIMEOUT_MILLIS = 250;
    private final NotifyOutboxWakeTransport transport;
    private final long timeoutMillis;

    /** 复用现有 RedisUtils 客户端的异步发布能力，不创建线程池或新的 Redis 客户端。 */
    public NotifyOutboxWakePublisher() {
        this(NotifyOutboxWakePublisher::publishViaRedis, PUBLISH_TIMEOUT_MILLIS);
    }

    /**
     * 模块内传输缝合点，生产等待上限固定为 250ms。
     * @param transport 返回异步发布结果的适配器
     * @param timeoutMillis 正数等待上限
     */
    NotifyOutboxWakePublisher(NotifyOutboxWakeTransport transport, long timeoutMillis) {
        if (timeoutMillis <= 0) throw new IllegalArgumentException("唤醒发布等待上限必须为正数");
        this.transport = transport;
        this.timeoutMillis = timeoutMillis;
    }

    /**
     * 事务提交后有界发布跨进程唤醒；丢失或超时不回灌已提交事务。
     *
     * @param event 本事务写出可 claim Outbox 的登记
     */
    @DsTxEventListener(phase = TransactionPhase.AFTER_COMMIT)
    public void publishAfterCommit(NotifyOutboxWakeRequestedEvent event) {
        if (event == null) {
            return;
        }
        NotifyOutboxWakeSignal signal = NotifyOutboxWakeSignal.wake(event.outboxId());
        Future<Long> pending = null;
        try {
            pending = transport.publish(NotifyOutboxWakeChannels.REDIS_CHANNEL, signal);
            pending.get(timeoutMillis, TimeUnit.MILLISECONDS);
        } catch (InterruptedException failure) {
            if (pending != null) pending.cancel(false);
            Thread.currentThread().interrupt();
            log.warn("notify outbox wake interrupted, outboxId={}, fallback poll remains", event.outboxId());
        } catch (ExecutionException | TimeoutException | RuntimeException failure) {
            if (pending != null) pending.cancel(false);
            log.warn("notify outbox cross-process wake publish failed, outboxId={}, reason={}, fallback poll remains",
                event.outboxId(), failure.getClass().getSimpleName());
        }
    }

    /**
     * 现有同步 publish 无独立等待上限，本事件适配器使用同一客户端的异步 Future。
     * @param channel 唤醒通道
     * @param signal 不含收件人、正文或凭据的载荷
     * @return 由现有 Redisson 事件循环完成的发布结果
     */
    private static Future<Long> publishViaRedis(String channel, NotifyOutboxWakeSignal signal) {
        return RedisUtils.getClient().getTopic(channel).publishAsync(signal);
    }

}

/**
 * 跨进程唤醒传输缝合点。生产实现复用 {@link RedisUtils#getClient()} 的异步发布。
 */
@FunctionalInterface
interface NotifyOutboxWakeTransport {

    /**
     * 向约定通道发布唤醒载荷。
     *
     * @param channel Redis 通道
     * @param signal  无 PII 唤醒载荷
     */
    Future<Long> publish(String channel, NotifyOutboxWakeSignal signal);
}

package org.namewta.notify.adapter.store;

import org.namewta.common.redis.utils.RedisUtils;
import org.namewta.notify.port.NotifyQuotaPort;
import org.springframework.stereotype.Component;

import java.time.Duration;

/**
 * 使用 Redis 原子计数实现发送配额。
 */
@Component
public class RedisNotifyQuotaAdapter implements NotifyQuotaPort {

    /**
     * 占用限额。
     *
     * @param key    计数键
     * @param limit  上限
     * @param window 窗口
     * @return 是否允许发送
     */
    @Override
    public boolean tryAcquire(String key, int limit, Duration window) {
        if (limit <= 0) {
            return true;
        }
        long value = RedisUtils.incrAtomicValue(key);
        if (value == 1) {
            RedisUtils.expire(key, window);
        }
        if (value <= limit) {
            return true;
        }
        RedisUtils.decrAtomicValue(key);
        return false;
    }

    /**
     * 回滚一次成功占用。
     *
     * @param key 计数键
     */
    @Override
    public void release(String key) {
        if (key == null || key.isBlank()) {
            return;
        }
        RedisUtils.decrAtomicValue(key);
    }
}

package org.namewta.notify.support.outbox;

import java.io.Serial;
import java.io.Serializable;

/**
 * 跨进程 Outbox 唤醒载荷。
