    /**
     * 构造不含业务字段的唤醒载荷。
     *
     * @param outboxId 可选 Outbox 主键 hint
     * @return 唤醒信号
     */
    public static NotifyOutboxWakeSignal wake(Long outboxId) {
        return new NotifyOutboxWakeSignal(TYPE_WAKE, outboxId);
    }
}

