package org.namewta.notify.service.runtime;

import lombok.RequiredArgsConstructor;
import org.namewta.common.mybatis.utils.IdGeneratorUtil;
import org.namewta.notify.dao.NotifyNotificationDao;
import org.namewta.notify.domain.entity.NotifyAttempt;
import org.namewta.notify.domain.entity.NotifyDelivery;
import org.namewta.notify.domain.entity.NotifyIntent;
import org.namewta.notify.domain.entity.NotifyOutbox;
import org.namewta.notify.domain.policy.NotificationAggregatePolicy;
import org.namewta.notify.domain.policy.NotificationDeliveryPolicy;
import org.namewta.notify.port.NotifyDispatchResultPort.Disposition;
import org.namewta.notify.port.NotifyDispatchResultPort.Result;
import org.springframework.stereotype.Service;

import java.util.Objects;

/** 结果写回规则；调用方必须经过 NotifyDispatchResultUseCase 的动态事务代理。 */
@Service
@RequiredArgsConstructor
public class NotifyDispatchResultService {
    private final NotifyNotificationDao dao;

    /** 锁序为 Intent → Outbox → Delivery，随后取数据库时间验证租约，阻止等锁期间过期的 owner。 */
    private NotifyOutbox lockActive(NotifyOutbox lease) {
        if (dao.lockIntent(lease.getIntentId()) == null) return null;
        NotifyOutbox current = dao.lockOutbox(lease.getOutboxId());
        if (current == null || !"PROCESSING".equals(current.getStatus())
            || lease.getLeaseOwner() == null || lease.getLeaseToken() == null
            || !Objects.equals(current.getIntentId(), lease.getIntentId())
            || !Objects.equals(current.getDeliveryId(), lease.getDeliveryId())
            || !Objects.equals(current.getLeaseOwner(), lease.getLeaseOwner())
            || !Objects.equals(current.getLeaseToken(), lease.getLeaseToken())) return null;
        return current;
    }

    /** 取完行锁后独立查询时钟，不能使用可能在等待锁之前固定的 SQL NOW 值。 */
    private boolean unexpired(NotifyOutbox outbox) {
        return outbox.getLeaseUntil() != null && outbox.getLeaseUntil().isAfter(dao.databaseNow());
    }

    /**
     * 续租也先锁后取时钟，防止 UPDATE 在等待锁前固定的 NOW 值复活租约。
     * @param lease 原领取的任务与 owner/token
     * @return 只有仍有效的租约才返回 true
     */
    public boolean renew(NotifyOutbox lease) {
        NotifyOutbox current = lockActive(lease);
        return current != null && unexpired(current)
            && dao.renewOutbox(current.getOutboxId(), current.getLeaseOwner(), current.getLeaseToken()) == 1;
    }

    /**
     * 原子保存尝试与当前结果；finish=0和任意写入冲突必须抛出以回滚整个短事务。
     * @param lease 原领取的任务与 owner/token
     * @param result 事务外 Provider 结果快照
     * @throws IllegalStateException 持有有效租约后的任何写入未影响一行
     */
    public void complete(NotifyOutbox lease, Result result) {
        NotifyOutbox outbox = lockActive(lease);
        if (outbox == null) return;
        NotifyDelivery delivery = dao.lockDelivery(outbox.getDeliveryId());
        if (!unexpired(outbox)) return;
        if (delivery == null || !Objects.equals(delivery.getIntentId(), outbox.getIntentId())) {
            outbox.setStatus("DONE"); finish(outbox); return;
        }
        boolean advanced = !"PENDING".equals(delivery.getStatus());
        if (!advanced || NotificationDeliveryPolicy.canAdvance(delivery.getStatus(), result.status())) {
            delivery.setStatus(result.status());
            delivery.setProviderKey(result.providerKey());
            delivery.setProviderMessageId(result.providerMessageId());
            delivery.setErrorCode(result.errorCode());
            delivery.setErrorMessage(result.errorMessage());
            if (success(delivery.getStatus()) && delivery.getAcceptedAt() == null) delivery.setAcceptedAt(dao.databaseNow());
            if ("DELIVERED".equals(delivery.getStatus()) && delivery.getDeliveredAt() == null) delivery.setDeliveredAt(dao.databaseNow());
        }
        int attemptNo = (delivery.getAttemptCount() == null ? 0 : delivery.getAttemptCount()) + 1;
        delivery.setAttemptCount(attemptNo);
        NotifyAttempt attempt = new NotifyAttempt();
        attempt.setAttemptId(IdGeneratorUtil.nextLongId()); attempt.setIntentId(outbox.getIntentId());
        attempt.setDeliveryId(delivery.getDeliveryId()); attempt.setAttemptNo(attemptNo);
        attempt.setProviderKey(result.providerKey()); attempt.setProviderMessageId(result.providerMessageId());
        attempt.setStatus(result.status()); attempt.setErrorCategory(result.errorCode());
        attempt.setErrorCode(result.errorCode()); attempt.setErrorMessage(result.errorMessage()); attempt.setCostTime(result.costTime());

        boolean failClosed = "FAILED".equals(delivery.getStatus()) && configFailure(result.errorCode());
        boolean waiting = "UNKNOWN".equals(delivery.getStatus());
        outbox.setAttemptCount((outbox.getAttemptCount() == null ? 0 : outbox.getAttemptCount()) + 1);
        outbox.setLastErrorCode(result.errorCode()); outbox.setLastErrorMessage(result.errorMessage());
        outbox.setStatus(advanced || success(delivery.getStatus()) || failClosed ? "DONE" : waiting ? "WAITING_RECEIPT" : "READY");
        if ("READY".equals(outbox.getStatus())) {
            outbox.setNextAttemptAt(dao.databaseNow().plusSeconds(Math.min(3600L, 1L << Math.min(outbox.getAttemptCount(), 10))));
            if (outbox.getAttemptCount() >= outbox.getMaxAttempts()) {
                outbox.setStatus("DEAD_LETTER"); delivery.setStatus("FAILED");
            } else delivery.setStatus("PENDING");
        }
        requireOne(dao.saveDeliveryResult(delivery));
        requireOne(dao.insert(attempt));
        finish(outbox);
        refreshAggregate(outbox.getIntentId());
    }

    /**
     * 无外部调用的编排也服从相同租约和事务，不能绕过结果 fence。
     * @param lease 原领取的任务与 owner/token
     * @param disposition 编排得出的等待、取消或关闭决定
     * @throws IllegalStateException 有效租约下的写入冲突
     */
    public void settle(NotifyOutbox lease, Disposition disposition) {
        NotifyOutbox outbox = lockActive(lease);
        if (outbox == null) return;
        NotifyDelivery delivery = dao.lockDelivery(outbox.getDeliveryId());
        if (!unexpired(outbox)) return;
        outbox.setStatus("DONE");
        if (delivery != null && "PENDING".equals(delivery.getStatus())) {
            if (disposition == Disposition.WAIT) {
                outbox.setStatus("READY"); outbox.setNextAttemptAt(dao.databaseNow().plusSeconds(30));
            } else if (disposition == Disposition.SKIP) {
                delivery.setStatus("CANCELLED"); requireOne(dao.saveDeliveryResult(delivery));
            }
        }
        finish(outbox);
        refreshAggregate(outbox.getIntentId());
    }

    /**
     * Intent 锁串行化同一通知的所有聚合；锁定读避免早先普通查询创建的 RR 快照。
     * @param intentId 通知意图主键，缺失时不写入
     * @throws IllegalStateException 聚合写入未影响一行
     */
    public void refreshAggregate(Long intentId) {
        NotifyIntent intent = dao.lockIntent(intentId);
        if (intent == null) return;
        var deliveries = dao.lockDeliveries(intentId);
        if (deliveries.isEmpty()) return;
        intent.setStatus(NotificationAggregatePolicy.aggregate(deliveries.stream().map(NotifyDelivery::getStatus).toList()).name());
        requireOne(dao.update(intent));
    }

    /** 完成 SQL 再次校验数据库租约时间；不得静默忽略零行结果。 */
    private void finish(NotifyOutbox outbox) { requireOne(dao.finishOutbox(outbox)); }

    /** 乐观冲突或缺行等同提交失败，交给动态事务恢复。 */
    private void requireOne(int count) {
        if (count != 1) throw new IllegalStateException("通知结果提交冲突");
    }

    /** 接受与送达是成功调度结果，接受本身并非最终送达。 */
    private boolean success(String status) { return "ACCEPTED".equals(status) || "DELIVERED".equals(status); }

    /** 配置或配额拒绝保持既有失败关闭语义，不自动换账号。 */
    private boolean configFailure(String code) {
        return code != null && (code.startsWith("UNBOUND") || code.startsWith("ACCOUNT_") || code.startsWith("MISSING_")
            || code.startsWith("SMS_") || code.endsWith("_QUOTA"));
    }
}

package org.namewta.notify.service.runtime;

import lombok.RequiredArgsConstructor;
import org.namewta.common.notify.core.NotifyClient;
import org.namewta.common.notify.model.NotifyContent;
import org.namewta.common.notify.model.NotifyRequest;
import org.namewta.common.notify.model.NotifyResult;
import org.namewta.common.notify.model.NotifyRichContent;
import org.namewta.common.notify.model.NotifyTemplateContent;
import org.namewta.common.notify.model.NotifyTarget;
import org.namewta.common.notify.exception.NotifyDeliveryException;
import org.namewta.common.json.utils.JsonUtils;
import org.namewta.notify.api.NotificationChannel;
import org.namewta.notify.api.InAppNotificationPort;
import org.namewta.notify.dao.NotifyConfigDao;
import org.namewta.notify.dao.NotifyNotificationDao;
import org.namewta.notify.domain.entity.NotifyChannelAccount;
import org.namewta.notify.domain.entity.NotifyDelivery;
import org.namewta.notify.domain.entity.NotifyIntent;
import org.namewta.notify.domain.entity.NotifyOutbox;
import org.namewta.notify.domain.entity.NotifySceneBinding;
import org.namewta.notify.port.NotifyDispatchPort;
import org.namewta.notify.port.NotifyDispatchResultPort;
import org.namewta.notify.port.NotifyDispatchResultPort.Disposition;
import org.namewta.notify.port.NotifyQuotaPort;
import org.namewta.notify.support.NotifySendPlanner;
import org.namewta.notify.support.NotifyTemplateRenderer;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.ObjectProvider;

import java.util.List;
import java.util.Map;

/**
 * 单条通知投递服务。
 *
 * <p>Provider 调用在数据库事务外执行，完成后以短事务更新 Attempt、Delivery 和 Intent。</p>
 */
@Service
@RequiredArgsConstructor
public class DispatchNotificationService implements NotifyDispatchPort {
    private final NotifyNotificationDao dao;
    private final NotifyClient notifyClient;
    private final ObjectProvider<InAppNotificationPort> inAppPort;
    private final NotifyConfigDao configDao;
    private final NotifyQuotaPort quotaPort;
    private final NotifyDispatchResultPort resultPort;

    /**
     * 执行一个 Outbox 任务，Provider I/O 在结果事务外；失效 owner 不写回。
     * @param outbox 本次领取的任务与 fencing token
     * @throws IllegalStateException 结果事务检测到写入冲突
     */
    public void dispatch(NotifyOutbox outbox) {
        NotifyOutbox leased = dao.outbox(outbox.getOutboxId());
        if (!leaseActive(leased, outbox)) return;
        outbox = leased;
        NotifyIntent intent = dao.intent(outbox.getIntentId());
        NotifyDelivery delivery = dao.delivery(outbox.getDeliveryId());
        if (intent == null || delivery == null || !"PENDING".equals(delivery.getStatus())) {
            resultPort.settle(outbox, Disposition.CLOSE);
            return;
        }
        if (!renewLease(outbox)) return;
        RouteDecision route = routeDecision(intent, delivery);
        if (route == RouteDecision.SKIP) {
            resultPort.settle(outbox, Disposition.SKIP);
            return;
        }
        if (route == RouteDecision.WAIT) {
            resultPort.settle(outbox, Disposition.WAIT);
            return;
        }
        long started = System.nanoTime();
        NotifyResult result = null;
        String errorCode = null;
        String errorMessage = null;
        try {
            if (NotificationChannel.IN_APP.name().equals(delivery.getChannel())) {
                InAppNotificationPort port = inAppPort.getIfAvailable();
                if (port == null) {
                    throw new IllegalStateException("站内通知端口未装配");
                }
                Map<String, Object> templateParams = JsonUtils.parseObject(intent.getTemplateParamsJson(), Map.class);
                String noticeType = templateParams == null ? null : String.valueOf(templateParams.getOrDefault("noticeType", ""));
                List<String> channels = templateParams == null ? List.of(delivery.getChannel())
                    : JsonUtils.parseArray(JsonUtils.toJsonString(templateParams.get("channels")), String.class);
                if (channels.isEmpty()) channels = List.of(delivery.getChannel());
                InAppNotificationPort.InAppSnapshot snapshot = new InAppNotificationPort.InAppSnapshot(
                    intent.getTitleSnapshot(), intent.getContentSnapshot(), intent.getPathSnapshot(),
                    noticeType, channels);
                port.persist(String.valueOf(intent.getIntentId()), snapshot, List.of(delivery.getUserId()));
                delivery.setStatus("DELIVERED");
                try {
                    port.pushRealtime(String.valueOf(intent.getIntentId()), snapshot, List.of(delivery.getUserId()));
                } catch (RuntimeException exception) {
                    // 站内信已经落库，实时提示失败只影响在线体验，不应触发重复写入。
                }
            } else {
                NotifySendPlanner.Plan plan = planChannel(intent, delivery);
                if (!plan.ok()) {
                    delivery.setStatus("FAILED");
                    errorCode = plan.errorCode();
                    errorMessage = plan.errorMessage();
                } else {
                    NotifyRequest request = NotifyRequest.builder()
                        .requestId(String.valueOf(delivery.getDeliveryId()))
                        .bizType(intent.getBizType())
                        .bizId(intent.getBizId())
                        .channel(org.namewta.common.notify.model.NotifyChannel.of(delivery.getChannel().toLowerCase()))
                        .providerKey(plan.providerKey())
                        .targets(List.of(target(delivery)))
                        .content(toContent(plan))
                        .idempotencyKey(String.valueOf(delivery.getDeliveryId()))
                        .build();
                    result = notifyClient.send(request);
                    delivery.setStatus(result.status().name());
                    if (!result.deliveries().isEmpty()) {
                        delivery.setProviderKey(result.providerKey());
                        delivery.setProviderMessageId(result.deliveries().getFirst().providerMessageId());
                        errorCode = result.deliveries().getFirst().errorCode();
                        errorMessage = result.deliveries().getFirst().errorMessage();
                    }
                }
            }
        } catch (NotifyDeliveryException exception) {
            result = exception.result();
            delivery.setStatus(result.status().name());
            if (!result.deliveries().isEmpty()) {
                delivery.setProviderKey(result.providerKey());
                delivery.setProviderMessageId(result.deliveries().getFirst().providerMessageId());
                errorCode = result.deliveries().getFirst().errorCode();
                errorMessage = result.deliveries().getFirst().errorMessage();
            }
        } catch (RuntimeException exception) {
            delivery.setStatus("UNKNOWN");
            errorCode = "DISPATCH_ERROR";
            errorMessage = exception.getClass().getSimpleName();
        }
        resultPort.complete(outbox, new NotifyDispatchResultPort.Result(delivery.getStatus(),
            result == null ? (NotificationChannel.IN_APP.name().equals(delivery.getChannel()) ? "in-app" : delivery.getProviderKey()) : result.providerKey(),
            delivery.getProviderMessageId(), errorCode, errorMessage,
            java.util.concurrent.TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - started)));
    }

    /** 调用前续租也由数据库判断有效期，不能复活已经过期的 owner。 */
    private boolean renewLease(NotifyOutbox outbox) {
        return resultPort.renew(outbox);
    }

    /** 预检只减少无效 I/O；最终权限以锁后的结果事务为准。 */
    private boolean leaseActive(NotifyOutbox current, NotifyOutbox claimed) {
        return current != null && "PROCESSING".equals(current.getStatus())
            && claimed.getLeaseOwner() != null && claimed.getLeaseToken() != null
            && java.util.Objects.equals(current.getLeaseOwner(), claimed.getLeaseOwner())
            && java.util.Objects.equals(current.getLeaseToken(), claimed.getLeaseToken())
            && current.getLeaseUntil() != null && current.getLeaseUntil().isAfter(dao.databaseNow());
    }

    /** 聚合重算同样经过短事务代理，供提交用例复用。 */
    public void refreshAggregate(Long intentId) { resultPort.refreshAggregate(intentId); }

    private NotifyContent toContent(NotifySendPlanner.Plan plan) {
        if (plan.mail()) {
            return new NotifyRichContent(plan.subject(), plan.body(), plan.html());
        }
        return new NotifyTemplateContent("sms", plan.smsTemplateCode(), plan.smsParams(), "");
    }

    private NotifySendPlanner.Plan planChannel(NotifyIntent intent, NotifyDelivery delivery) {
        String sceneCode = intent.getSceneCode() == null || intent.getSceneCode().isBlank()
            ? intent.getTemplateCode() : intent.getSceneCode();
        NotifySceneBinding binding = configDao.findBinding(sceneCode, delivery.getChannel());
        NotifyChannelAccount account = binding == null ? null : configDao.findAccount(binding.getAccountId());
        @SuppressWarnings("unchecked")
        Map<String, Object> raw = JsonUtils.parseObject(intent.getTemplateParamsJson(), Map.class);
        return NotifySendPlanner.plan(sceneCode, delivery.getChannel(), delivery.getTargetValue(),
            NotifyTemplateRenderer.stringify(raw), binding, account, quotaPort);
    }

    private NotifyTarget target(NotifyDelivery delivery) {
        return switch (delivery.getChannel()) {
            case "SMS" -> NotifyTarget.phone(delivery.getTargetValue());
            case "MAIL" -> NotifyTarget.email(delivery.getTargetValue());
            default -> NotifyTarget.user(String.valueOf(delivery.getUserId()));
        };
    }

    private boolean isSuccess(String status) { return "ACCEPTED".equals(status) || "DELIVERED".equals(status); }
    private RouteDecision routeDecision(NotifyIntent intent, NotifyDelivery delivery) {
        if (!"ORDERED_FALLBACK".equals(intent.getStrategy()) && !"ESCALATION".equals(intent.getStrategy())) return RouteDecision.READY;
        List<NotifyDelivery> prior = dao.priorDeliveries(intent.getIntentId(), delivery.getRecipientId(), delivery.getDeliveryId());
        if (prior.isEmpty()) return RouteDecision.READY;
        NotifyDelivery previous = prior.getLast();
        if ("ORDERED_FALLBACK".equals(intent.getStrategy())) {
            return prior.stream().anyMatch(item -> isSuccess(item.getStatus())) ? RouteDecision.SKIP
                : "FAILED".equals(previous.getStatus()) || "UNDELIVERABLE".equals(previous.getStatus())
                ? RouteDecision.READY : RouteDecision.WAIT;
        }
        return "UNDELIVERABLE".equals(previous.getStatus()) || "FAILED".equals(previous.getStatus())
            ? RouteDecision.READY : RouteDecision.WAIT;
    }
    private enum RouteDecision { READY, WAIT, SKIP }
}

package org.namewta.notify.service.runtime;

import lombok.RequiredArgsConstructor;
import org.namewta.notify.domain.entity.NotifyOutbox;
import org.namewta.notify.dao.NotifyNotificationDao;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.util.List;
import java.util.UUID;

/**
 * Outbox 领取服务，以短事务锁定任务并建立租约。
 */
@Service
@RequiredArgsConstructor
public class NotifyOutboxClaimService {
    private final NotifyNotificationDao dao;

    /**
     * 领取到期任务；事务结束后才能执行供应商 I/O。
     *
     * @param owner 当前 Worker 标识
     * @return 已建立租约的任务
     */
    public List<NotifyOutbox> claim(String owner) {
        LocalDateTime nowUtc = dao.databaseNow();
        LocalDateTime leaseUntil = nowUtc.plusSeconds(60);
        List<NotifyOutbox> candidates = dao.claimCandidates(nowUtc, 50);
        return candidates.stream().filter(outbox -> {
            String token = UUID.randomUUID().toString();
            if (dao.claimOutbox(outbox.getOutboxId(), owner, token, leaseUntil, nowUtc) != 1) return false;
            outbox.setStatus("PROCESSING");
            outbox.setLeaseOwner(owner);
            outbox.setLeaseToken(token);
            outbox.setLeaseUntil(leaseUntil);
            return true;
        }).toList();
    }
}

package org.namewta.notify.service.runtime;

import lombok.RequiredArgsConstructor;
import org.namewta.notify.domain.entity.NotifyMessage;
import org.namewta.notify.domain.entity.NotifyMessageRecipient;
import org.namewta.notify.dao.NotifyNotificationDao;
import org.namewta.notify.domain.vo.NotifyInboxMessageVo;
import org.namewta.common.json.utils.JsonUtils;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.util.List;

/**
 * 通知中心收件箱服务，先读取持久化消息，再执行已见已读状态变更。
 */
@Service
@RequiredArgsConstructor
public class NotifyInboxService {
    private final NotifyNotificationDao dao;

    /** 查询用户收件箱。 */
    public List<NotifyInboxMessageVo> list(Long userId) {
        List<NotifyMessageRecipient> recipients = dao.messageRecipients(userId, 500);
        if (recipients.isEmpty()) return List.of();
        var messages = dao.messages(recipients.stream().map(NotifyMessageRecipient::getMessageId).toList()).stream()
            .collect(java.util.stream.Collectors.toMap(NotifyMessage::getMessageId, java.util.function.Function.identity()));
        return recipients.stream().filter(recipient -> messages.containsKey(recipient.getMessageId()))
            .map(recipient -> {
                NotifyMessage message = messages.get(recipient.getMessageId());
                NotifyInboxMessageVo vo = new NotifyInboxMessageVo();
                vo.setMessageId(message.getMessageId());
                vo.setCategory(message.getCategory());
                vo.setNoticeType(message.getNoticeType());
                vo.setChannels(message.getChannelsJson() == null ? List.of("IN_APP") : JsonUtils.parseArray(message.getChannelsJson(), String.class));
                vo.setType(message.getType());
                vo.setSource(message.getSource());
                vo.setTitle(message.getTitle());
                vo.setMessage(message.getMessage());
                vo.setContent(message.getContent());
                vo.setPath(message.getPath());
                vo.setCreateTime(message.getCreateTime());
                if (recipient != null) {
                    vo.setSeenTime(recipient.getSeenTime());
                    vo.setReadTime(recipient.getReadTime());
                }
                return vo;
            }).toList();
    }

    /** 标记消息已见或已读，重复调用保持幂等。 */
    public boolean mark(Long messageId, Long userId, boolean read) {
        NotifyMessageRecipient item = dao.messageRecipient(messageId, userId);
        if (item == null) return false;
        if (item.getSeenTime() == null) item.setSeenTime(LocalDateTime.now());
        if (read && item.getReadTime() == null) item.setReadTime(LocalDateTime.now());
        return dao.update(item) > 0;
    }

    /** 将当前用户全部收件消息标记为已见已读。 */
    public int markAll(Long userId) {
        return dao.markAllMessages(userId, LocalDateTime.now());
    }
}

package org.namewta.notify.service.runtime;

import lombok.RequiredArgsConstructor;
import org.namewta.common.core.exception.ServiceException;
import org.namewta.common.json.utils.JsonUtils;
import org.namewta.common.mybatis.utils.IdGeneratorUtil;
import org.namewta.notify.api.*;
import org.namewta.notify.domain.entity.NotifyDelivery;
import org.namewta.notify.domain.entity.NotifyIntent;
import org.namewta.notify.domain.entity.NotifyOutbox;
import org.namewta.notify.domain.entity.NotifyRecipient;
import org.namewta.notify.dao.NotifyNotificationDao;
import org.namewta.notify.support.outbox.NotifyOutboxWakeRequestedEvent;
import org.namewta.system.api.UserService;
import org.namewta.system.api.domain.UserDTO;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.dao.DuplicateKeyException;

import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/**
 * 统一通知应用服务实现。
 *
 * <p>提交阶段只写业务事实和 Outbox，不执行 Provider I/O，保证业务事务可恢复。</p>
 */
@Service
@RequiredArgsConstructor
public class NotificationApplicationRuntimeService {

    private final NotifyNotificationDao dao;
    private final UserService userService;
    private final DispatchNotificationService dispatchService;
    private final ApplicationEventPublisher events;

    public NotificationReceipt submit(NotificationCommand command) {
        validate(command);
        NotifyIntent duplicated = findDuplicate(command);
        if (duplicated != null) {
            return receipt(duplicated, dao.deliveries(duplicated.getIntentId()));
        }

        List<ResolvedRecipient> users = resolveUsers(command).stream().distinct().toList();
        if (users.isEmpty()) throw new ServiceException("所选范围没有可接收通知的正常用户");
        long intentId = IdGeneratorUtil.nextLongId();
        NotifyIntent intent = new NotifyIntent();
        intent.setIntentId(intentId);
        intent.setAppId(command.appId());
        intent.setSceneCode(command.sceneCode());
        intent.setBizType(command.bizType());
        intent.setBizId(command.bizId());
        intent.setTemplateCode(command.templateCode());
        intent.setTemplateParamsJson(JsonUtils.toJsonString(command.templateParams()));
        intent.setStrategy(command.strategy().name());
        intent.setMode(command.mode().name());
        intent.setPriority(command.priority());
        intent.setScheduledAt(toLocal(command.scheduledAt()));
        intent.setExpiresAt(toLocal(command.expiresAt()));
        intent.setIdempotencyKey(command.idempotencyKey());
        intent.setStatus(NotificationStatus.QUEUED.name());
        intent.setTitleSnapshot(stringValue(command.templateParams(), "title", command.templateCode()));
        intent.setContentSnapshot(stringValue(command.templateParams(), "content", command.templateCode()));
        intent.setPathSnapshot(stringValue(command.templateParams(), "path", null));
        intent.setMetadataJson(JsonUtils.toJsonString(command.metadata()));
        intent.setVersion(0);
        try {
            dao.insert(intent);
        } catch (DuplicateKeyException duplicate) {
            NotifyIntent existing = findDuplicate(command);
            if (existing != null) {
                return receipt(existing, dao.deliveries(existing.getIntentId()));
            }
            throw duplicate;
        }

        List<NotifyDelivery> deliveries = new ArrayList<>();
        List<NotifyOutbox> outboxes = new ArrayList<>();
        // 秒精度列可能向上舍入；立即任务取数据库当前整秒，保证提交后的首次 wake 已可 claim。
        LocalDateTime availableAt = command.scheduledAt() == null
            ? dao.databaseNow().withNano(0) : toLocal(command.scheduledAt());
        for (ResolvedRecipient user : users) {
            NotifyRecipient recipient = new NotifyRecipient();
            recipient.setRecipientId(IdGeneratorUtil.nextLongId());
            recipient.setIntentId(intentId);
            recipient.setRecipientType(command.recipientType());
            recipient.setRecipientKey(user.key());
            recipient.setUserId(user.userId());
            recipient.setTargetSnapshotJson(JsonUtils.toJsonString(Map.of(
                "phone", Objects.toString(user.phone(), ""),
                "email", Objects.toString(user.email(), ""))));
            recipient.setStatus("ACTIVE");
            dao.insert(recipient);
            for (NotificationChannel channel : command.channels()) {
                NotifyDelivery delivery = new NotifyDelivery();
                delivery.setDeliveryId(IdGeneratorUtil.nextLongId());
                delivery.setIntentId(intentId);
                delivery.setRecipientId(recipient.getRecipientId());
                delivery.setUserId(user.userId());
                delivery.setChannel(channel.name());
                String targetValue = targetValue(channel, user);
                delivery.setTargetValue(targetValue);
                delivery.setStatus(blank(targetValue) ? "UNDELIVERABLE" : "PENDING");
                delivery.setAttemptCount(0);
                delivery.setVersion(0);
                dao.insert(delivery);
                deliveries.add(delivery);

                if (!"PENDING".equals(delivery.getStatus())) {
                    delivery.setErrorCode("TARGET_UNAVAILABLE");
                    delivery.setErrorMessage("通知目标缺少有效联系方式");
                    dao.update(delivery);
                    continue;
                }

                NotifyOutbox outbox = new NotifyOutbox();
                outbox.setOutboxId(IdGeneratorUtil.nextLongId());
                outbox.setIntentId(intentId);
                outbox.setDeliveryId(delivery.getDeliveryId());
                outbox.setStatus("READY");
                outbox.setAvailableAt(availableAt);
                outbox.setAttemptCount(0);
                outbox.setNextAttemptAt(outbox.getAvailableAt());
                outbox.setMaxAttempts(5);
                dao.insert(outbox);
                outboxes.add(outbox);
            }
        }
        if (outboxes.isEmpty()) {
            dispatchService.refreshAggregate(intentId);
        } else {
            requestOutboxWake(outboxes.getFirst().getOutboxId());
        }
        return receipt(dao.intent(intentId), dao.deliveries(intentId));
    }

    public NotificationSnapshot query(NotificationQuery query) {
        if (query == null || query.notificationId() == null) {
            throw new ServiceException("通知编号不能为空");
        }
        Long notificationId = parsePositiveId(query.notificationId());
        NotifyIntent intent = dao.intent(notificationId);
        if (intent == null) {
            throw new ServiceException("通知不存在");
        }
        List<NotifyDelivery> deliveries = dao.deliveries(intent.getIntentId());
        return new NotificationSnapshot(String.valueOf(intent.getIntentId()),
            status(intent.getStatus()), parseTime(intent.getCreateTime()),
            deliveries.stream().map(item -> new NotificationReceipt.DeliveryReceipt(
                item.getUserId() == null ? null : String.valueOf(item.getUserId()), NotificationChannel.valueOf(item.getChannel()),
                status(item.getStatus()), item.getProviderMessageId())).toList());
    }

    public RetryReceipt retry(NotificationRetryCommand command) {
        if (command == null || command.notificationId() == null) {
            throw new ServiceException("通知编号不能为空");
        }
        NotifyIntent intent = dao.lockIntent(parsePositiveId(command.notificationId()));
        if (intent == null) {
            throw new ServiceException("通知不存在");
        }
        List<NotifyDelivery> deliveries = dao.lockDeliveries(intent.getIntentId()).stream()
            .filter(item -> List.of("FAILED", "UNKNOWN").contains(item.getStatus())).toList();
        boolean queued = false;
        Long wakeHint = null;
        for (NotifyDelivery delivery : deliveries) {
            if (dao.markDeliveryForRetry(delivery.getDeliveryId()) != 1) continue;
            LocalDateTime now = dao.databaseNow().withNano(0);
            if (dao.requeueOutbox(delivery.getDeliveryId(), now) == 0) {
                NotifyOutbox outbox = new NotifyOutbox();
                outbox.setOutboxId(IdGeneratorUtil.nextLongId());
                outbox.setIntentId(intent.getIntentId());
                outbox.setDeliveryId(delivery.getDeliveryId());
                outbox.setStatus("READY");
                outbox.setAvailableAt(now);
                outbox.setNextAttemptAt(now);
                outbox.setAttemptCount(0);
                outbox.setMaxAttempts(5);
                dao.insert(outbox);
                wakeHint = outbox.getOutboxId();
            }
            queued = true;
        }
        intent.setStatus(NotificationStatus.QUEUED.name());
        dao.update(intent);
        if (queued) {
            requestOutboxWake(wakeHint);
        }
        return new RetryReceipt(command.notificationId(), NotificationStatus.QUEUED);
    }

    public CancelReceipt cancel(NotificationCancelCommand command) {
        if (command == null || command.notificationId() == null) {
            throw new ServiceException("通知编号不能为空");
        }
        NotifyIntent intent = dao.lockIntent(parsePositiveId(command.notificationId()));
        if (intent == null) {
            throw new ServiceException("通知不存在");
        }
        if (Set.of("DELIVERED", "CANCELLED", "FAILED").contains(intent.getStatus())) {
            throw new ServiceException("当前通知状态不允许取消");
        }
        intent.setStatus(NotificationStatus.CANCELLED.name());
        dao.update(intent);
        dao.updateDeliveryStatus(intent.getIntentId(), "PENDING", "CANCELLED");
        return new CancelReceipt(command.notificationId(), NotificationStatus.CANCELLED);
    }

    /**
     * 在当前 {@code @DSTransactional} 内登记提交后唤醒；真正的 Redis 发布由 AFTER_COMMIT 监听器执行。
     *
     * @param outboxIdHint 可选 Outbox 主键 hint，允许为 {@code null}
     */
    private void requestOutboxWake(Long outboxIdHint) {
        events.publishEvent(new NotifyOutboxWakeRequestedEvent(outboxIdHint));
    }

    private void validate(NotificationCommand command) {
        if (command == null || blank(command.appId()) || blank(command.sceneCode())
            || blank(command.templateCode()) || command.channels().isEmpty()) {
            throw new ServiceException("通知应用、场景、模板和渠道不能为空");
        }
        if (command.channels().stream().anyMatch(Objects::isNull)) {
            throw new ServiceException("通知渠道不能为空");
        }
        String recipientType = command.recipientType() == null
            ? "" : command.recipientType().trim().toUpperCase(java.util.Locale.ROOT);
        if (!Set.of("ALL", "USER", "PHONE", "EMAIL").contains(recipientType)) {
            throw new ServiceException("接收者类型不受支持");
        }
        List<String> recipientIds = command.recipientIds();
        if ("ALL".equals(recipientType) && !recipientIds.isEmpty()) {
            throw new ServiceException("全部用户通知不能同时指定接收者编号");
        }
        if (!"ALL".equals(recipientType) && recipientIds.isEmpty()) {
            throw new ServiceException("接收者不能为空");
        }
        if ("USER".equals(recipientType)) {
            try {
                if (recipientIds.stream().anyMatch(value -> Long.parseLong(value) <= 0)) {
                    throw new NumberFormatException();
                }
            } catch (NumberFormatException exception) {
                throw new ServiceException("用户编号必须为正整数");
            }
        }
        if (command.expiresAt() != null && command.scheduledAt() != null
            && command.expiresAt().isBefore(command.scheduledAt())) {
            throw new ServiceException("通知截止时间不能早于计划时间");
        }
    }

    private NotifyIntent findDuplicate(NotificationCommand command) {
        if (blank(command.idempotencyKey())) {
            return null;
        }
        return dao.intentByIdempotency(command.appId(), command.idempotencyKey());
    }

    private List<ResolvedRecipient> resolveUsers(NotificationCommand command) {
        if ("USER".equalsIgnoreCase(command.recipientType())) {
            List<Long> ids = command.recipientIds().stream().map(Long::valueOf).toList();
            return userService.selectNotificationUsers(ids).stream().filter(Objects::nonNull)
                .map(user -> new ResolvedRecipient(user.getUserId(), String.valueOf(user.getUserId()), user.getPhoneNumber(), user.getEmail()))
                .toList();
        }
        if ("ALL".equalsIgnoreCase(command.recipientType())) {
            if (command.recipientIds().isEmpty()) {
                List<ResolvedRecipient> recipients = new ArrayList<>();
                int offset = 0;
                List<UserDTO> batch;
                do {
                    batch = Objects.requireNonNullElse(userService.selectAllActiveUsers(offset, 1_000), List.of());
                    recipients.addAll(batch.stream().map(user -> new ResolvedRecipient(user.getUserId(), String.valueOf(user.getUserId()), user.getPhoneNumber(), user.getEmail())).toList());
                    if (recipients.size() > 100_000) throw new ServiceException("全体用户通知超过单次发送上限");
                    offset += batch.size();
                } while (!batch.isEmpty());
                return recipients;
            }
            throw new ServiceException("全部用户通知不能同时指定接收者编号");
        }
        if ("PHONE".equalsIgnoreCase(command.recipientType()) || "SMS".equalsIgnoreCase(command.recipientType())) {
            return command.recipientIds().stream().map(value -> new ResolvedRecipient(null, value, value, null)).toList();
        }
        if ("EMAIL".equalsIgnoreCase(command.recipientType()) || "MAIL".equalsIgnoreCase(command.recipientType())) {
            return command.recipientIds().stream().map(value -> new ResolvedRecipient(null, value, null, value)).toList();
        }
        throw new ServiceException("接收者类型仅支持 USER、ALL、PHONE 和 EMAIL");
    }

    private String targetValue(NotificationChannel channel, ResolvedRecipient user) {
        return switch (channel) {
            case IN_APP -> user.userId() == null ? null : String.valueOf(user.userId());
            case SMS -> user.phone();
            case MAIL -> user.email();
        };
    }

    private NotificationReceipt receipt(NotifyIntent intent, List<NotifyDelivery> deliveries) {
        boolean queued = deliveries.stream().anyMatch(item -> "PENDING".equals(item.getStatus()));
        boolean followUpRequired = deliveries.stream().anyMatch(item -> !"IN_APP".equals(item.getChannel())
            && ("ACCEPTED".equals(item.getStatus()) || "UNKNOWN".equals(item.getStatus())));
        return new NotificationReceipt(String.valueOf(intent.getIntentId()), status(intent.getStatus()),
            queued, followUpRequired, deliveries.stream().map(item ->
            new NotificationReceipt.DeliveryReceipt(item.getUserId() == null ? null : String.valueOf(item.getUserId()),
                NotificationChannel.valueOf(item.getChannel()), status(item.getStatus()), item.getProviderMessageId())).toList());
    }

    /** 将持久化状态转换为稳定的应用层状态，避免内部状态泄漏到公共 API。 */
    private NotificationStatus status(String value) {
        if (value == null) return NotificationStatus.UNKNOWN;
        if ("PENDING".equals(value) || "READY".equals(value)) {
            return NotificationStatus.QUEUED;
        }
        try {
            return NotificationStatus.valueOf(value);
        } catch (IllegalArgumentException ex) {
            return NotificationStatus.UNKNOWN;
        }
    }
    private String stringValue(Map<String, Object> values, String key, String fallback) {
        Object value = values.get(key);
        return value == null ? fallback : String.valueOf(value);
    }
    private LocalDateTime toLocal(Instant value) { return value == null ? null : LocalDateTime.ofInstant(value, ZoneOffset.UTC); }
    private Instant parseTime(java.time.LocalDateTime value) {
        return value == null ? null : value.toInstant(ZoneOffset.UTC);
    }
    private boolean blank(String value) { return value == null || value.isBlank(); }

    private Long parsePositiveId(String value) {
        try {
            long id = Long.parseLong(value);
            if (id <= 0) throw new NumberFormatException();
            return id;
        } catch (NumberFormatException exception) {
            throw new ServiceException("通知编号必须为正整数");
        }
    }

    private record ResolvedRecipient(Long userId, String key, String phone, String email) {
    }
}

