        assertAll(
            () -> assertEquals("\"sms\"", json),
            () -> assertEquals(NotifyChannel.MAIL, restored),
            () -> assertTrue(resultJson.contains("\"channel\":\"sms\"")),
            () -> assertEquals(result, restoredResult)
        );
    }
}

