import type { createNotificationService } from '@namewta/domain-notify';
import type { NotifyUserCandidatePage, NotifyUserTypeOption } from '@namewta/domain-notify';
import type { Ref } from 'vue';

export interface NotifyDictOption {
  label: string;
  value: string;
  listClass?: string;
}

/** 由宿主组合系统公开目录，通知页面不依赖系统领域的内部实现。 */
export interface NotifyUserDirectory {
  searchUsers: (keyword: string, page: number, pageSize: number) => Promise<{ data: NotifyUserCandidatePage }>;
  usersByIds: (ids: readonly (string | number)[]) => Promise<{ data: NotifyUserCandidatePage['rows'] }>;
  userTypes: () => Promise<{ data: NotifyUserTypeOption[] }>;
}

export interface NotifyWebRuntime {
  /** 宿主推送重连/到达时通知收件箱刷新；返回解绑函数。 */
  subscribeInbox?: (handler: () => void) => () => void;
  /** 收件箱已读状态变更后，请宿主同步消息盒子。 */
  inboxChanged?: () => void;
  service: ReturnType<typeof createNotificationService>;
  hasPermission: (permission: string) => boolean;
  navigate: (path: string) => Promise<void> | void;
  dicts: (...types: string[]) => Record<string, Readonly<Ref<NotifyDictOption[]>>>;
  directory: NotifyUserDirectory;
}

import type { NotifyUserCandidate } from '@namewta/domain-notify';
import { computed, onScopeDispose, ref, watch, type Ref } from 'vue';
import type { NotifyUserDirectory } from '../runtime';

/** 候选结果与已选名单独立管理，查询翻页不会丢失用户已确认的选择。 */
export function useRecipientSelection(
  directory: NotifyUserDirectory,
  ids: Ref<Array<string | number>>,
  onError: (message: string) => void
) {
  const keyword = ref('');
  const page = ref(1);
  const pageSize = 20;
  const rows = ref<NotifyUserCandidate[]>([]);
  const total = ref(0);
  const loading = ref(false);
  const searched = ref(false);
  const cache = ref(new Map<string, NotifyUserCandidate>());
  const selectedIds = computed(() => new Set(ids.value.map(String)));
  const selected = computed(() => [...selectedIds.value].map(id => cache.value.get(id) ?? { userId: id }));
  const allChecked = computed(
    () => rows.value.length > 0 && rows.value.every(row => selectedIds.value.has(String(row.userId)))
  );
  const someChecked = computed(
    () => rows.value.some(row => selectedIds.value.has(String(row.userId))) && !allChecked.value
  );
  let generation = 0;
  let disposed = false;
  let timer: ReturnType<typeof setTimeout> | undefined;

  function remember(users: NotifyUserCandidate[]) {
    users.forEach(user => cache.value.set(String(user.userId), user));
  }

  async function search(nextPage = 1) {
    clearTimeout(timer);
    const request = ++generation;
    const value = keyword.value.trim();
    page.value = nextPage;
    rows.value = [];
    total.value = 0;
    searched.value = !!value;
    loading.value = !!value;
    if (!value) return;
    try {
      const result = await directory.searchUsers(value, nextPage, pageSize);
      if (disposed || request !== generation) return;
      rows.value = result.data.rows.filter(row => row.status === '0');
      total.value = result.data.total;
      remember(rows.value);
    } catch (error) {
      if (!disposed && request === generation) onError(error instanceof Error ? error.message : '用户搜索失败，请重试');
    } finally {
      if (request === generation) loading.value = false;
    }
  }

  watch(
    keyword,
    () => {
      clearTimeout(timer);
      ++generation;
      rows.value = [];
      total.value = 0;
      loading.value = false;
      searched.value = false;
      if (keyword.value.trim()) timer = setTimeout(() => void search(), 300);
    },
    { flush: 'sync' }
  );

  function toggle(user: NotifyUserCandidate, checked: boolean) {
    const next = new Set(selectedIds.value);
    if (checked) {
      next.add(String(user.userId));
      remember([user]);
    } else next.delete(String(user.userId));
    ids.value = [...next];
  }

  function togglePage(checked: boolean) {
    const next = new Set(selectedIds.value);
    rows.value.forEach(user => (checked ? next.add(String(user.userId)) : next.delete(String(user.userId))));
    remember(rows.value);
    ids.value = [...next];
  }

  async function restore() {
    if (!ids.value.length) return;
    try {
      const result = await directory.usersByIds(ids.value);
      if (!disposed) remember(result.data);
    } catch (error) {
      if (!disposed) onError(error instanceof Error ? error.message : '已选用户信息加载失败');
    }
  }
  void restore();
  onScopeDispose(() => {
    disposed = true;
    ++generation;
    clearTimeout(timer);
  });

  return {
    keyword,
    page,
    pageSize,
    rows,
    total,
    loading,
    searched,
    selected,
    selectedIds,
    allChecked,
    someChecked,
    search,
    toggle,
    togglePage
  };
}

import { afterEach, describe, expect, it, vi } from 'vitest';
import { effectScope, ref } from 'vue';
import type { NotifyUserDirectory } from '../runtime';
import { useRecipientSelection } from './useRecipientSelection';

const user = (id: number) => ({ userId: id, userName: `user${id}`, status: '0' });
const scopes: ReturnType<typeof effectScope>[] = [];
function setup(initial: Array<string | number> = []) {
  const directory: NotifyUserDirectory = {
    searchUsers: vi.fn(async () => ({ data: { rows: [user(1), user(2)], total: 30 } })),
    usersByIds: vi.fn(async () => ({ data: [user(1)] })),
    userTypes: vi.fn(async () => ({ data: [] }))
  };
  const ids = ref(initial);
  const error = vi.fn();
  const scope = effectScope();
  scopes.push(scope);
  const picker = scope.run(() => useRecipientSelection(directory, ids, error))!;
  return { directory, ids, error, picker, scope };
}
afterEach(() => {
  scopes.splice(0).forEach(scope => scope.stop());
  vi.useRealTimers();
});

describe('通知接收者选择', () => {
  it('空白不请求；输入防抖并只查询最后一个关键词', async () => {
    vi.useFakeTimers();
    const { picker, directory } = setup();
    await picker.search();
    picker.keyword.value = 'a';
    await vi.advanceTimersByTimeAsync(150);
    picker.keyword.value = 'admin';
    await vi.advanceTimersByTimeAsync(300);
    expect(directory.searchUsers).toHaveBeenCalledTimes(1);
    expect(directory.searchUsers).toHaveBeenCalledWith('admin', 1, 20);
    expect(picker.rows.value).toHaveLength(2);
  });

  it('跨关键词/分页保留选择，取消当前页全选不影响其他已选', async () => {
    const { picker, directory, ids } = setup();
    picker.keyword.value = 'user';
    await picker.search();
    picker.togglePage(true);
    expect(ids.value).toEqual(['1', '2']);
    vi.mocked(directory.searchUsers).mockResolvedValue({ data: { rows: [user(3)], total: 30 } });
    await picker.search(2);
    picker.togglePage(true);
    expect(ids.value).toEqual(['1', '2', '3']);
    picker.togglePage(false);
    expect(ids.value).toEqual(['1', '2']);
    picker.keyword.value = 'different';
    await picker.search();
    expect(picker.selected.value.map(row => row.userName)).toEqual(['user1', 'user2']);
    picker.toggle(user(1), false);
    expect(ids.value).toEqual(['2']);
  });

  it('新输入使旧响应失效，旧请求不会覆盖候选名单', async () => {
    const { picker, directory } = setup();
    let finish!: (result: Awaited<ReturnType<NotifyUserDirectory['searchUsers']>>) => void;
    vi.mocked(directory.searchUsers).mockImplementationOnce(
      () =>
        new Promise(resolve => {
          finish = resolve;
        })
    );
    picker.keyword.value = 'old';
    const pending = picker.search();
    picker.keyword.value = 'new';
    await picker.search();
    finish({ data: { rows: [user(99)], total: 1 } });
    await pending;
    expect(picker.rows.value.map(row => row.userId)).toEqual([1, 2]);
    expect(picker.loading.value).toBe(false);
  });

  it('恢复草稿名单并去重；失败后能再次查询且loading复位', async () => {
    const { picker, directory, error } = setup(['1', 1]);
    await Promise.resolve();
    expect(picker.selected.value).toEqual([user(1)]);
    vi.mocked(directory.searchUsers).mockRejectedValueOnce(new Error('网络中断'));
    picker.keyword.value = 'user';
    await picker.search();
    expect(error).toHaveBeenCalledWith('网络中断');
    expect(picker.loading.value).toBe(false);
    await picker.search();
    expect(picker.rows.value).toHaveLength(2);
  });

  it('离开弹窗会取消待执行防抖，不产生多余请求', async () => {
    vi.useFakeTimers();
    const { picker, directory, scope } = setup();
    picker.keyword.value = 'user';
    scope.stop();
    await vi.advanceTimersByTimeAsync(500);
    expect(directory.searchUsers).not.toHaveBeenCalled();
  });
});

